window.GEN_BANK = [{"section": "reading", "type": "sentence_pos", "level": 1, "points": 2, "q": "다음 글을 읽고 ‘비가 올 것 같습니다.’가 들어갈 가장 알맞은 위치를 고르십시오.", "qGl": "Read the following passage and choose the most appropriate position for the sentence ‘비가 올 것 같습니다.’", "passage": "오늘은 날씨가 흐립니다. ㉠ 아침에 창문을 열었습니다. ㉡ 하늘에 구름이 많았습니다. ㉢ 저는 가방에 우산을 넣었습니다. ㉣ 집을 나왔습니다.", "passageGl": "Today the weather is cloudy. ㉠ In the morning I opened the window. ㉡ There were many clouds in the sky. ㉢ I put an umbrella in my bag. ㉣ I left the house.", "options": [{"t": "㉠", "gl": "position 1 (after the first sentence)"}, {"t": "㉡", "gl": "position 2 (after opening the window)"}, {"t": "㉢", "gl": "position 3 (after seeing many clouds)"}, {"t": "㉣", "gl": "position 4 (after packing the umbrella)"}], "correct": 2, "explain": "The sentence ‘비가 올 것 같습니다’ logically follows the observation that there were many clouds, and it explains why the speaker put an umbrella in the bag.", "traps": ["Position 1 is too early because the sky has not been described yet.", "Position 2 is awkward because the speaker has only opened the window and has not mentioned clouds.", "Position 4 is too late because the umbrella has already been packed."], "tip": "문장이 들어갈 위치는 앞뒤 문장의 원인과 결과를 연결해 보세요.", "optExplain": ["오답: ㉠ 앞은 날씨가 흐리다는 첫 문장 뒤인데, 비가 올 것 같다는 판단은 구름을 본 뒤에 나오는 것이 자연스럽습니다.", "오답: ㉡ 앞은 창문을 열었다는 문장 뒤인데, 아직 구름을 보지 않았으므로 비 예상이 어색합니다.", "정답: ㉢ 앞에 하늘에 구름이 많다는 내용이 있으므로 비가 올 것 같다고 예상하고 우산을 넣는 흐름이 자연스럽습니다.", "오답: ㉣ 앞은 이미 우산을 넣은 뒤이므로 비 예상이 먼저 나와야 자연스럽습니다."], "optExplainEn": ["Wrong: Putting it after the first sentence about cloudy weather is less natural because the prediction of rain should come after seeing the clouds.", "Wrong: Putting it after opening the window is awkward because the clouds have not been mentioned yet.", "Correct: Placing it after the sentence about many clouds logically leads to predicting rain and then putting an umbrella in the bag.", "Wrong: Placing it after already packing the umbrella is unnatural because the expectation of rain should come before."], "tipEn": "For sentence-position questions, check how the inserted sentence connects the cause and result before and after.", "freq": 2, "freqNote": "TOPIK I 읽기 31~33 · 문장 위치 파악", "id": "AII-baac88"}, {"section": "reading", "type": "main_idea", "level": 1, "points": 2, "q": "이 글의 주제는 무엇입니까?", "qGl": "What is the topic of this passage?", "passage": "지난 주말에 가족과 함께 바다에 갔습니다. 바다에서 수영을 하고 모래성을 만들었습니다. 저녁에는 맛있는 해산물을 먹었습니다. 아주 즐거웠습니다.", "passageGl": "Last weekend I went to the sea with my family. At the sea we swam and built a sandcastle. In the evening we ate delicious seafood. It was very enjoyable.", "options": [{"t": "주말 가족 여행", "gl": "a weekend family trip"}, {"t": "학교 시험", "gl": "a school exam"}, {"t": "요리 방법", "gl": "a cooking method"}, {"t": "날씨 정보", "gl": "weather information"}], "correct": 0, "explain": "The passage consistently describes what the speaker did with their family on a weekend trip to the sea, so the topic is a weekend family trip.", "traps": ["A school exam is not mentioned at all.", "The passage does not explain how to cook anything.", "No weather information is provided."], "tip": "주제는 글 전체에서 반복되거나 가장 많이 설명하는 대상을 고르세요.", "optExplain": ["정답: 글에서 주말에 가족과 바다에 가서 논 이야기를 했으므로 주말 가족 여행이 주제입니다.", "오답: 학교 시험에 대한 내용은 전혀 나오지 않았습니다.", "오답: 요리 방법을 설명하는 내용이 아닙니다.", "오답: 날씨 정보는 다루지 않았습니다."], "optExplainEn": ["Correct: The passage talks about going to the sea with family on the weekend, so the topic is a weekend family trip.", "Wrong: There is no mention of a school exam.", "Wrong: The passage does not explain a cooking method.", "Wrong: Weather information is not covered."], "tipEn": "For main-idea questions, choose the subject that is consistently described throughout the whole passage.", "freq": 2, "freqNote": "TOPIK I 읽기 25~27 · 중심 생각/주제 파악", "id": "AII-fda31b"}, {"section": "reading", "type": "vocab", "level": 1, "points": 2, "q": "다음 밑줄 친 ‘아주’와 의미가 가장 비슷한 것을 고르십시오.", "qGl": "Choose the option with the closest meaning to the underlined word ‘아주’.", "passage": "이 가방은 <u>아주</u> 큽니다. 그래서 무겁습니다.", "passageGl": "This bag is very big. Therefore it is heavy.", "options": [{"t": "조금", "gl": "a little"}, {"t": "정말", "gl": "really"}, {"t": "빨리", "gl": "quickly"}, {"t": "항상", "gl": "always"}], "correct": 1, "explain": "In this sentence ‘아주’ expresses a high degree, so the closest meaning is ‘정말’, which can also mean ‘really/very’.", "traps": ["‘조금’ means a small degree, which is the opposite of ‘아주’.", "‘빨리’ relates to speed, not degree.", "‘항상’ relates to time, not degree."], "tip": "비슷한 뜻 고르기는 문장에서 그 단어가 강조하는 정도나 상황을 먼저 파악하세요.", "optExplain": ["오답: ‘조금’은 정도가 작다는 뜻이므로 ‘아주’와 반대 의미입니다.", "정답: ‘아주’는 ‘정말’과 비슷하게 정도가 크다는 의미입니다.", "오답: ‘빨리’는 속도가 빠르다는 뜻으로 의미가 다릅니다.", "오답: ‘항상’은 시간의 반복을 나타내는 말로 의미가 다릅니다."], "optExplainEn": ["Wrong: ‘조금’ means a small degree, which is the opposite of ‘아주’.", "Correct: ‘아주’ is similar to ‘정말’ in expressing a high degree.", "Wrong: ‘빨리’ means quickly and has a different meaning.", "Wrong: ‘항상’ means always and refers to repeated time."], "tipEn": "For synonym questions, first identify what the word is emphasizing in the sentence—degree, manner, or time.", "freq": 2, "freqNote": "TOPIK I 읽기 16~18 · 어휘 의미 파악", "id": "AII-503178"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "다음 글을 읽고 맞지 않는 것을 고르십시오.", "qGl": "Read the passage and choose the statement that is not correct.", "passage": "저는 수진입니다. 오늘 엄마하고 시장에 갔습니다. 시장에서 사과하고 우유를 샀습니다. 내일은 학교에 가요.", "passageGl": "I am Sujin. Today I went to the market with my mom. At the market I bought apples and milk. Tomorrow I go to school.", "options": [{"t": "저는 수진입니다.", "gl": "I am Sujin."}, {"t": "오늘 시장에 갔습니다.", "gl": "I went to the market today."}, {"t": "시장에서 빵을 샀습니다.", "gl": "I bought bread at the market."}, {"t": "내일 학교에 가요.", "gl": "I go to school tomorrow."}], "correct": 2, "explain": "The passage says she bought apples and milk at the market, not bread. Therefore, the statement about buying bread is not correct.", "traps": ["Option 1 matches the first sentence.", "Option 2 matches the second sentence.", "Option 4 matches the last sentence."], "tip": "글 속의 정보를 하나씩 비교하세요. 다른 단어(빵/사과)를 조심하세요.", "optExplain": ["오답: 글의 첫 문장과 같습니다.", "오답: 글에서 오늘 엄마하고 시장에 갔다고 했습니다.", "정답: 글에서는 빵을 샀다고 하지 않았습니다. 사과하고 우유를 샀습니다.", "오답: 글의 마지막 문장과 같습니다."], "optExplainEn": ["Wrong: This matches the first sentence of the passage.", "Wrong: The passage says she went to the market today with her mom.", "Correct: The passage does not say she bought bread; she bought apples and milk.", "Wrong: This matches the last sentence of the passage."], "tipEn": "Compare each option with the information in the passage. Watch out for changed words like bread vs. apples.", "freq": 2, "freqNote": "TOPIK I 읽기 31~33 · 짧은 글 이해", "id": "AII-56870e"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "다음 글을 읽고 두 사람이 만나는 곳을 고르십시오.", "qGl": "Read the passage and choose the place where the two people meet.", "passage": "저는 주말에 친구하고 영화를 봅니다. 영화는 두 시에 시작합니다. 우리는 한 시에 영화관에서 만납니다.", "passageGl": "I watch a movie with my friend on the weekend. The movie starts at two o'clock. We meet at the movie theater at one o'clock.", "options": [{"t": "집", "gl": "house"}, {"t": "학교", "gl": "school"}, {"t": "영화관", "gl": "movie theater"}, {"t": "식당", "gl": "restaurant"}], "correct": 2, "explain": "The passage states clearly: 우리는 한 시에 영화관에서 만납니다. So the meeting place is the movie theater.", "traps": ["House is not mentioned as a meeting place.", "School is not mentioned in the passage.", "Restaurant is not mentioned in the passage."], "tip": "장소를 묻는 문제는 '에서' 앞의 단어를 찾으세요.", "optExplain": ["오답: 글에서 만나는 장소로 집이 나오지 않습니다.", "오답: 학교는 글에 나오지 않습니다.", "정답: 글에서 영화관에서 만난다고 했습니다.", "오답: 식당은 글에 나오지 않습니다."], "optExplainEn": ["Wrong: The passage does not mention a house as the meeting place.", "Wrong: School is not mentioned in the passage.", "Correct: The passage says they meet at the movie theater.", "Wrong: Restaurant is not mentioned in the passage."], "tipEn": "For place questions, look for the word before '-에서'.", "freq": 2, "freqNote": "TOPIK I 읽기 34~36 · 장소·정보 파악", "id": "AII-c858b2"}, {"section": "reading", "type": "grammar", "level": 1, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "저는 주말에 책을 ( ) 싶어요.", "passageGl": "I want to ___ a book on the weekend.", "options": [{"t": "읽", "gl": "read (verb stem)"}, {"t": "읽고", "gl": "read (correct with -고 싶다)"}, {"t": "읽어", "gl": "read (connective form)"}, {"t": "읽으", "gl": "read (wrong stem)"}], "correct": 1, "explain": "The pattern -고 싶다 attaches to the verb stem 읽 + 고 = 읽고 싶어요, meaning 'want to read.'", "traps": ["'읽' is only the stem; it cannot connect directly to '-고 싶다'.", "'읽어' is used with '-요' or '-서', not before '-고 싶다'.", "'읽으' is not the correct stem form; the correct stem is '읽'."], "tip": "‘-고 싶다’는 동사 어간 뒤에 붙어요. 받침이 있는 동사도 어간에 바로 '-고'를 붙입니다.", "optExplain": ["오답: '읽'은 동사 어간이지만 '-고 싶다'와 바로 연결할 수 없습니다.", "정답: '읽' + '-고 싶다' → '읽고 싶어요' = 읽기를 원하다.", "오답: '읽어'는 '-어요'나 '-어서'에 쓰이지만 '-고 싶다' 앞에는 쓰지 않습니다.", "오답: '읽으'는 올바른 어간이 아닙니다. '읽'이 어간입니다."], "optExplainEn": ["Wrong: '읽' is only the verb stem and cannot connect directly to '-고 싶다'.", "Correct: '읽' + '-고 싶다' → '읽고 싶어요' means 'want to read'.", "Wrong: '읽어' is used with '-어요' or '-어서', not before '-고 싶다'.", "Wrong: '읽으' is not the correct stem form; the correct stem is '읽'."], "tipEn": "‘-고 싶다’ attaches directly to the verb stem. For verbs with a final consonant, add '-고' to the stem.", "freq": 2, "freqNote": "TOPIK I 읽기 37~40 · 문법·어휘", "id": "AII-f1cebf"}, {"section": "reading", "type": "sentence_pos", "level": 1, "points": 2, "q": "다음 문장이 들어갈 곳을 고르십시오. 그리고 자전거를 탔습니다.", "qGl": "Choose where the following sentence fits. And we rode bicycles.", "passage": "저는 토요일에 친구와 공원에 갔습니다. ( ㉠ ) 공원에서 김밥을 먹었습니다. ( ㉡ ) 우리는 사진을 찍었습니다. ( ㉢ ) 집에 갔습니다. ( ㉣ )", "passageGl": "On Saturday, I went to the park with my friend. (㉠) We ate kimbap at the park. (㉡) We took pictures. (㉢) We went home. (㉣)", "options": [{"t": "㉠", "gl": "position ㉠"}, {"t": "㉡", "gl": "position ㉡"}, {"t": "㉢", "gl": "position ㉢"}, {"t": "㉣", "gl": "position ㉣"}], "correct": 1, "explain": "The sentence 'And we rode bicycles' logically follows the lunch activity and precedes taking pictures, creating a natural sequence of park activities.", "traps": ["Placing the bicycle ride before eating is possible, but the sentence begins with 'And', making it less natural before lunch has been mentioned.", "Placing it after taking pictures creates an awkward order because the statement then interrupts the conclusion of the outing.", "Placing it after going home is illogical because one cannot ride a bicycle after returning home."], "tip": "‘그리고’나 ‘-고’처럼 앞 활동이 끝난 뒤 이어지는 문장을 찾으세요.", "optExplain": ["오답: 식사를 하기 전에 자전거를 타는 것은 ‘그리고’의 흐름과 어울리지 않습니다.", "정답: 점심을 먹은 후에 자전거를 타고 사진을 찍는 순서가 자연스럽습니다.", "오답: 사진을 찍은 다음에 자전거를 타면 집에 가는 흐름이 끊깁니다.", "오답: 집에 간 다음에는 자전거를 탈 수 없습니다."], "optExplainEn": ["Wrong: Riding a bicycle before eating does not match the 'and' flow.", "Correct: The order of eating lunch, riding bicycles, and then taking pictures is natural.", "Wrong: Riding a bicycle after taking pictures interrupts the flow of going home.", "Wrong: You cannot ride a bicycle after going home."], "tipEn": "Look for a sentence that continues after the previous activity using connectors like '그리고' or '-고'.", "freq": 2, "freqNote": "TOPIK I 읽기 31~33 · 문장 위치", "id": "AII-c1fcb0"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 3, "q": "이 사람은 주말에 무엇을 했습니까?", "qGl": "What did this person do on the weekend?", "passage": "지난 주말에 가족과 함께 할머니 댁에 갔습니다. 할머니께서 맛있는 음식을 많이 만들어 주셨습니다. 저는 할머니와 함께 시장에도 갔습니다. 시장에서 과일을 샀습니다.", "passageGl": "Last weekend, I went to my grandmother's house with my family. Grandmother made a lot of delicious food for us. I also went to the market with my grandmother. We bought fruit at the market.", "options": [{"t": "친구를 만났습니다.", "gl": "Met a friend"}, {"t": "할머니 댁에 갔습니다.", "gl": "Went to grandmother's house"}, {"t": "영화를 봤습니다.", "gl": "Watched a movie"}, {"t": "학교에서 공부했습니다.", "gl": "Studied at school"}], "correct": 1, "explain": "The first sentence clearly states that the person went to grandmother's house with family on the weekend.", "traps": ["The passage does not mention meeting a friend; it mentions family and grandmother.", "No movie or watching is mentioned.", "No school or studying is mentioned."], "tip": "첫 문장에서 장소와 사람을 확인하면 주제를 쉽게 찾을 수 있습니다.", "optExplain": ["오답: 친구를 만났다는 내용은 지문에 없습니다. 가족과 할머니 댁에 갔습니다.", "정답: 첫 문장에서 주말에 가족과 함께 할머니 댁에 갔다고 했습니다.", "오답: 영화를 봤다는 내용은 지문에 없습니다.", "오답: 학교에서 공부했다는 내용은 지문에 없습니다."], "optExplainEn": ["Wrong: The passage does not mention meeting a friend; it says they went to grandmother's house with family.", "Correct: The first sentence says they went to grandmother's house with family on the weekend.", "Wrong: There is no mention of watching a movie.", "Wrong: There is no mention of studying at school."], "tipEn": "Check the place and people in the first sentence to easily find the main topic.", "freq": 2, "freqNote": "TOPIK I 읽기 40~42 · 짧은 글 이해", "id": "AII-2f74e8"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 3, "q": "학생들은 무엇을 준비해야 합니까?", "qGl": "What should students prepare?", "passage": "다음 주 수요일에 학교에서 소풍을 갑니다. 장소는 남산공원입니다. 아침 9시까지 학교 운동장에 모이세요. 점심 도시락과 물을 준비하세요.", "passageGl": "Next Wednesday, the school will go on a picnic. The place is Namsan Park. Please gather in the school playground by 9 a.m. Please prepare a lunchbox and water.", "options": [{"t": "책과 공책", "gl": "Books and notebooks"}, {"t": "도시락과 물", "gl": "Lunchbox and water"}, {"t": "우산과 모자", "gl": "Umbrella and hat"}, {"t": "카메라와 가방", "gl": "Camera and bag"}], "correct": 1, "explain": "The notice says participants should prepare a lunchbox and water.", "traps": ["Books and notebooks are not mentioned in the notice.", "Umbrella and hat are not mentioned.", "Camera and bag are not mentioned."], "tip": "안내문은 날짜, 장소, 준비물 순서로 읽으면 핵심 정보를 찾기 쉽습니다.", "optExplain": ["오답: 책과 공책은 준비하라고 하지 않았습니다.", "정답: 안내문에 점심 도시락과 물을 준비하라고 했습니다.", "오답: 우산과 모자는 지문에 없습니다.", "오답: 카메라와 가방은 지문에 없습니다."], "optExplainEn": ["Wrong: The notice does not ask students to bring books and notebooks.", "Correct: The notice says to prepare a lunchbox and water.", "Wrong: An umbrella and hat are not mentioned.", "Wrong: A camera and bag are not mentioned."], "tipEn": "Read notices in the order of date, place, and items to prepare to find key information easily.", "freq": 2, "freqNote": "TOPIK I 읽기 40~42 · 안내문 이해", "id": "AII-a89926"}, {"section": "reading", "type": "grammar", "level": 1, "points": 2, "q": "빈칸에 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "저는 아침( ) 빵을 먹습니다.", "passageGl": "I eat bread in the morning.", "options": [{"t": "에", "gl": "time particle 'at/on/in'"}, {"t": "에서", "gl": "location particle 'at/in/on'"}, {"t": "을", "gl": "object particle"}, {"t": "와", "gl": "connective particle 'and/with'"}], "correct": 0, "explain": "The blank follows '아침' (morning), which is a time noun. The particle '에' is used with time expressions to indicate when an action takes place, so '아침에' is correct.", "traps": ["'에서' marks a location where an action occurs, not a time.", "'을' marks an object of a verb, but '아침' is not the object here.", "'와' means 'and/with' and cannot link a time noun to a verb phrase in this context."], "tip": "Remember: time nouns like 아침, 점심, 저녁, 주말 take the particle '에' to express 'at/on/in' the time.", "optExplain": ["정답: '아침'은 시간 명사이므로 시간을 나타내는 조사 '에'가 붙어 '아침에'가 됩니다.", "오답: '에서'는 장소에서 행동이 일어날 때 쓰는 조사이므로 시간 명사인 '아침'에는 알맞지 않습니다.", "오답: '을'은 목적격 조사로, '빵'처럼 동작의 대상에 붙어야 하므로 '아침' 뒤에는 올 수 없습니다.", "오답: '와'는 '~와/과'로 명사와 명사를 연결하거나 함께함을 나타내므로 이 자리에는 어울리지 않습니다."], "optExplainEn": ["Correct: '아침' is a time noun, so the time particle '에' is added to form '아침에'.", "Wrong: '에서' is used when an action occurs at a place, so it does not fit the time noun '아침'.", "Wrong: '을' is an object particle and must attach to the object of an action like '빵', not to '아침'.", "Wrong: '와' links nouns or means 'together with', so it is not suitable in this position."], "tipEn": "Remember: time nouns like morning, lunch, dinner, and weekend take the particle '에' to express 'at/on/in' the time.", "freq": 2, "freqNote": "TOPIK I 읽기 1~4 · 조사/시제", "id": "AII-6a0970"}, {"section": "listening", "type": "intent", "level": 1, "points": 3, "q": "가: 뭘 사고 싶어요?\n나: 저는 운동화가 사고 싶어요.\n가: 그럼, 이 운동화는 어때요?\n나: 좋아요. 이걸로 주세요.", "qGl": "A: What do you want to buy?\nB: I want to buy sneakers.\nA: Then how about these sneakers?\nB: They're good. I'll take these.", "passage": "", "passageGl": "", "options": [{"t": "운동화를 사려고 한다.", "gl": "Intends to buy sneakers."}, {"t": "운동화를 신어 보려고 한다.", "gl": "Intends to try on sneakers."}, {"t": "운동화를 고쳐 주려고 한다.", "gl": "Intends to repair sneakers."}, {"t": "운동화를 보여 주려고 한다.", "gl": "Intends to show sneakers."}], "correct": 0, "explain": "The woman says 'I want to buy sneakers' and 'I'll take these', clearly showing her intention to purchase sneakers.", "traps": ["Option 2: No mention of trying on shoes.", "Option 3: No mention of repairing.", "Option 4: Showing is what the shopkeeper does, not the woman's intention."], "tip": "Listen for key phrases like '사고 싶어요' (want to buy) and '주세요' (please give me) that signal a purchase intention.", "optExplain": ["정답: 여자가 '운동화가 사고 싶어요'라고 말하고 '이걸로 주세요'라고 하여 구매 의도를 분명히 밝혔습니다.", "오답: 신어 보는 행동에 대한 언급이 전혀 없습니다.", "오답: 수리에 관한 말은 한 마디도 나오지 않았습니다.", "오답: 보여 주는 것은 가게 주인의 행동이며, 여자의 의도가 아닙니다."], "optExplainEn": ["Correct: The woman says 'I want to buy sneakers' and 'I'll take these', clearly expressing her intention to buy.", "Wrong: There is no mention of trying them on.", "Wrong: There is no mention of repairing them.", "Wrong: Showing the sneakers is the shopkeeper's action, not the woman's intention."], "tipEn": "Listen for key phrases like '사고 싶어요' (want to buy) and '주세요' (please give me) that signal a purchase intention.", "freq": 2, "freqNote": "TOPIK I 듣기 13~16 · 의도 파악", "audioHint": "나: 저는 운동화가 사고 싶어요.", "id": "AII-af5ebd"}, {"section": "listening", "type": "grammar", "level": 1, "points": 3, "q": "가: 어디에 가요?\n나: 친구를 만나(   ) 학교에 가요.", "qGl": "A: Where are you going?\nB: I'm going to school (   ) meet my friend.", "passage": "", "passageGl": "", "options": [{"t": "-고", "gl": "and (connective)"}, {"t": "-러", "gl": "in order to (purpose)"}, {"t": "-면", "gl": "if/when"}, {"t": "-지만", "gl": "but"}], "correct": 1, "explain": "The phrase '친구를 만나( ) 학교에 가요' requires a purpose connective. '-러' is used with motion verbs to indicate the purpose of going, so '만나러 가요' means 'go to meet'.", "traps": ["Option 1: '-고' simply connects two actions, not expressing purpose.", "Option 3: '-면' is used for conditions, not purpose.", "Option 4: '-지만' means 'but', which does not fit the context."], "tip": "Remember that '-러' is attached to verb stems and followed by motion verbs like 가다, 오다 to express going/coming for that action.", "optExplain": ["오답: '-고'는 두 동작을 단순히 연결하며 목적의 의미가 없습니다.", "정답: '-러'는 동작 동사와 결합하여 '가다'의 목적을 나타냅니다. '만나러 가요'는 만나기 위해 간다는 뜻입니다.", "오답: '-면'은 조건을 나타내며 문장에 적합하지 않습니다.", "오답: '-지만'은 '그러나'의 뜻으로 글의 흐름상 맞지 않습니다."], "optExplainEn": ["Wrong: '-고' merely connects two actions without expressing purpose.", "Correct: '-러' indicates the purpose of going with motion verbs, so '만나러 가요' means 'go to meet'.", "Wrong: '-면' is used for conditions, not purpose.", "Wrong: '-지만' means 'but' and doesn't fit the context."], "tipEn": "Remember that '-러' is attached to verb stems and followed by motion verbs like 가다, 오다 to express going/coming for that action.", "freq": 2, "freqNote": "TOPIK I 듣기 23~25 · 문법", "audioHint": "나: 친구를 만나러 학교에 가요.", "id": "AII-9d7d7e"}, {"section": "listening", "type": "comprehension", "level": 1, "points": 4, "q": "가: 이번 주말에 뭐 할 거예요?\n나: 친구랑 같이 테니스를 칠 거예요.\n가: 좋겠네요. 저도 테니스를 배우고 싶어요.\n나: 그럼 같이 배워요.", "qGl": "A: What are you going to do this weekend?\nB: I'm going to play tennis with a friend.\nA: That sounds great. I want to learn tennis too.\nB: Then let's learn together.", "passage": "", "passageGl": "", "options": [{"t": "남자는 주말에 영화를 볼 것이다.", "gl": "The man will watch a movie on the weekend."}, {"t": "여자는 테니스를 칠 것이다.", "gl": "The woman will play tennis."}, {"t": "남자는 친구와 테니스를 칠 것이다.", "gl": "The man will play tennis with his friend."}, {"t": "여자는 테니스를 배우지 않을 것이다.", "gl": "The woman will not learn tennis."}], "correct": 2, "explain": "The man says, 'I'm going to play tennis with a friend,' so option 3 matches exactly.", "traps": ["Option 1: The man didn't mention a movie.", "Option 2: The woman wants to learn, not play, and no mention of her playing.", "Option 4: The woman expresses interest in learning and the man suggests they learn together, so she is likely to learn."], "tip": "Focus on who is speaking and what each person says. Match the detail precisely; don't confuse the subjects.", "optExplain": ["오답: 남자가 영화를 볼 거라고 말하지 않았습니다.", "오답: 여자는 테니스를 배우고 싶다고 했지, 직접 치겠다고 한 말은 없습니다.", "정답: 남자가 '친구랑 같이 테니스를 칠 거예요'라고 말했기 때문에 내용이 일치합니다.", "오답: 여자는 배우고 싶다고 했고, 남자가 같이 배우자고 하여 배울 가능성이 높습니다."], "optExplainEn": ["Wrong: The man didn't say anything about watching a movie.", "Wrong: The woman only said she wants to learn, not that she will play.", "Correct: The man clearly said 'I'm going to play tennis with a friend,' matching this option.", "Wrong: The woman expressed a desire to learn and the man invited her to learn together, so she likely will learn."], "tipEn": "Focus on who is speaking and what each person says. Match the detail precisely; don't confuse the subjects.", "freq": 2, "freqNote": "TOPIK I 듣기 27~30 · 내용 이해", "audioHint": "나: 친구랑 같이 테니스를 칠 거예요.", "id": "AII-f2b457"}, {"section": "listening", "type": "topic", "level": 1, "points": 2, "q": "남자: 지난 주말에 뭐 했어요?\n여자: 친구하고 영화를 봤어요.\n남자: 영화가 재미있었어요?\n여자: 네, 아주 재미있었어요.\n무엇에 대해 이야기하고 있습니까?", "qGl": "Man: What did you do last weekend? Woman: I saw a movie with a friend. Man: Was the movie fun? Woman: Yes, it was really fun. What are they talking about?", "passage": "", "passageGl": "", "audioHint": "남자: 주말에 뭐 했어요? 여자: 친구하고 영화 봤어요.", "options": [{"t": "영화", "gl": "movie"}, {"t": "운동", "gl": "exercise"}, {"t": "쇼핑", "gl": "shopping"}, {"t": "여행", "gl": "travel"}], "correct": 0, "explain": "The dialogue contains repeated references to 영화, such as '영화를 봤어요' and '영화가 재미있었어요?', so the topic is movie.", "traps": ["운동 is not mentioned at all in the conversation.", "쇼핑 is not mentioned at all in the conversation.", "여행 is not mentioned at all in the conversation."], "tip": "Listen for repeated nouns in TOPIK I listening topic questions; the repeated word is usually the answer.", "optExplain": ["정답: 두 사람이 ‘영화를 봤어요’, ‘영화가 재미있었어요’라고 말하므로 영화에 대해 이야기하고 있습니다.", "오답: ‘운동’은 대화에 나오지 않았습니다.", "오답: ‘쇼핑’은 대화에 나오지 않았습니다.", "오답: ‘여행’은 대화에 나오지 않았습니다."], "optExplainEn": ["Correct: They talk about a movie, saying 'I saw a movie' and 'Was the movie fun?'", "Wrong: 'Exercise' does not appear in the dialogue.", "Wrong: 'Shopping' does not appear in the dialogue.", "Wrong: 'Travel' does not appear in the dialogue."], "tipEn": "Listen for repeated nouns in TOPIK I listening topic questions; the repeated word is usually the answer.", "freq": 2, "freqNote": "TOPIK I 듣기 4~6 · 주제 고르기", "id": "AII-534b5d"}, {"section": "listening", "type": "grammar", "level": 1, "points": 2, "q": "가: 뭐 먹고 싶어요?\n나: ________", "qGl": "A: What do you want to eat? B: ________", "passage": "", "passageGl": "", "audioHint": "가: 뭐 먹고 싶어요? 나: ...", "options": [{"t": "비빔밥을 먹고 싶어요.", "gl": "I want to eat bibimbap."}, {"t": "비빔밥을 먹었어요.", "gl": "I ate bibimbap."}, {"t": "비빔밥을 먹을 수 있어요.", "gl": "I can eat bibimbap."}, {"t": "비빔밥을 먹지 마세요.", "gl": "Don't eat bibimbap."}], "correct": 0, "explain": "The question uses -고 싶어요 to ask what someone wants to eat, so the correct answer must also use -고 싶어요.", "traps": ["먹었어요 is past tense, so it does not answer a question about what someone wants.", "먹을 수 있어요 expresses ability, not desire.", "먹지 마세요 is a prohibition and cannot be B's answer to A's question."], "tip": "When a TOPIK I listening question asks '뭐 -고 싶어요?', choose the response that repeats '-고 싶어요'.", "optExplain": ["정답: ‘뭐 먹고 싶어요?’라고 원하는 것을 물었으므로 ‘먹고 싶어요’로 대답하는 것이 맞습니다.", "오답: ‘먹었어요’는 과거를 말하므로 원하는 것을 묻는 질문에 어울리지 않습니다.", "오답: ‘먹을 수 있어요’는 가능을 말하므로 질문과 연결되지 않습니다.", "오답: ‘먹지 마세요’는 금지를 말하므로 질문에 대한 대답이 아닙니다."], "optExplainEn": ["Correct: Since the question asks what you want to eat, answering with 'want to eat' is correct.", "Wrong: 'Ate' is past tense, so it does not fit a question about desire.", "Wrong: 'Can eat' expresses ability, not desire.", "Wrong: 'Don't eat' is a prohibition, not an answer to the question."], "tipEn": "When a TOPIK I listening question asks '뭐 -고 싶어요?', choose the response that repeats '-고 싶어요'.", "freq": 2, "freqNote": "TOPIK I 듣기 7~10 · 문법형 대답 고르기", "id": "AII-14a5d1"}, {"section": "listening", "type": "topic", "level": 1, "points": 2, "q": "남자: 오늘 날씨가 어때요?\n여자: 눈이 와요. 아주 추워요.\n남자: 따뜻한 옷을 입으세요.\n여자: 네, 고마워요.\n무엇에 대해 이야기하고 있습니까?", "qGl": "Man: How is the weather today? Woman: It's snowing. It's very cold. Man: Wear warm clothes. Woman: Yes, thank you. What are they talking about?", "passage": "", "passageGl": "", "audioHint": "남자: 오늘 날씨 어때요? 여자: 눈이 와요. 아주 추워요.", "options": [{"t": "날씨", "gl": "weather"}, {"t": "음식", "gl": "food"}, {"t": "가족", "gl": "family"}, {"t": "운동", "gl": "exercise"}], "correct": 0, "explain": "The dialogue mentions 날씨, 눈, and 추워요, all of which point to the topic of weather.", "traps": ["음식 is not mentioned in the dialogue.", "가족 is not mentioned in the dialogue.", "운동 is not mentioned in the dialogue."], "tip": "In TOPIK I listening topic questions, the first question often reveals the topic: '날씨가 어때요?' means the topic is weather.", "optExplain": ["정답: 대화에서 ‘날씨’, ‘눈’, ‘추워요’를 말하므로 날씨에 대해 이야기하고 있습니다.", "오답: ‘음식’은 대화에 나오지 않았습니다.", "오답: ‘가족’은 대화에 나오지 않았습니다.", "오답: ‘운동’은 대화에 나오지 않았습니다."], "optExplainEn": ["Correct: The dialogue mentions weather, snow, and cold, so the topic is weather.", "Wrong: 'Food' does not appear in the dialogue.", "Wrong: 'Family' does not appear in the dialogue.", "Wrong: 'Exercise' does not appear in the dialogue."], "tipEn": "In TOPIK I listening topic questions, the first question often reveals the topic: '날씨가 어때요?' means the topic is weather.", "freq": 2, "freqNote": "TOPIK I 듣기 4~6 · 주제 고르기", "id": "AII-af21e6"}, {"section": "listening", "type": "place", "level": 1, "points": 2, "q": "여자: 지금 어디에 가요? \n남자: 배가 고파서 점심을 먹으러 식당에 가요.", "qGl": "Woman: Where are you going now? \nMan: I'm hungry, so I'm going to the restaurant to eat lunch.", "passage": "", "passageGl": "", "options": [{"t": "학교", "gl": "school"}, {"t": "식당", "gl": "restaurant"}, {"t": "서점", "gl": "bookstore"}, {"t": "병원", "gl": "hospital"}], "correct": 1, "explain": "The man says he is going to the restaurant (식당) to eat lunch because he is hungry. This directly matches the place being asked about.", "traps": ["학교 (school) might be confused with a daily routine place, but no mention of studying or classes.", "서점 (bookstore) is unrelated to eating lunch, so it’s not implied.", "병원 (hospital) is not a place to eat a meal, and there’s no health-related context."], "tip": "In place-asking conversations, listen for destination-related verbs (e.g., 가다) and purpose markers like -(으)러. Keywords like ‘먹으러’ and ‘식당’ will directly point to the location.", "optExplain": ["오답: 대화에서 학교와 관련된 말이 없습니다.", "정답: 남자가 '식당에 가요'라고 말합니다.", "오답: 서점에 대한 이야기가 나오지 않습니다.", "오답: 병원은 식사와 무관합니다."], "optExplainEn": ["Wrong: There is no mention of school in the dialogue.", "Correct: The man says 'I'm going to the restaurant'.", "Wrong: There is no talk about a bookstore.", "Wrong: A hospital is not related to eating."], "tipEn": "In place-asking conversations, listen for destination-related verbs (e.g., 가다) and purpose markers like -(으)러. Keywords like ‘먹으러’ and ‘식당’ will directly point to the location.", "freq": 2, "freqNote": "TOPIK I 듣기 6~8 · 장소 고르기", "audioHint": "여자: 어디에 가요? 남자: 점심 먹으러 식당에 가요.", "id": "AII-675e76"}, {"section": "listening", "type": "topic", "level": 1, "points": 2, "q": "남자: 오늘 날씨가 정말 춥네요. \n여자: 네, 바람도 많이 불어요. 감기 조심하세요.", "qGl": "Man: The weather is really cold today. \nWoman: Yes, and the wind is blowing a lot. Be careful not to catch a cold.", "passage": "", "passageGl": "", "options": [{"t": "음식", "gl": "food"}, {"t": "쇼핑", "gl": "shopping"}, {"t": "날씨", "gl": "weather"}, {"t": "운동", "gl": "exercise"}], "correct": 2, "explain": "The conversation revolves around the cold weather, wind, and a warning about catching a cold, all indicators of the topic being ‘weather’.", "traps": ["음식 (food) is not mentioned at all; no talk of eating or dishes.", "쇼핑 (shopping) is unrelated; nothing about buying or stores.", "운동 (exercise) is not referenced; no mention of physical activity."], "tip": "For topic-identification questions, focus on repeated nouns and adjectives. Here ‘날씨’, ‘춥네요’, ‘바람’, ‘감기’ all cluster around weather. Related expressions often signal the theme.", "optExplain": ["오답: 대화에서 음식에 관한 말이 없습니다.", "오답: 쇼핑과 관련된 표현이 전혀 없습니다.", "정답: '날씨가 춥네요'와 '바람', '감기' 등 날씨 주제 대화입니다.", "오답: 운동에 대한 내용은 나오지 않습니다."], "optExplainEn": ["Wrong: There is no talk about food in the dialogue.", "Wrong: No expressions related to shopping appear.", "Correct: 'The weather is cold', 'wind', and 'cold' make the topic weather.", "Wrong: No content about exercise is mentioned."], "tipEn": "For topic-identification questions, focus on repeated nouns and adjectives. Here ‘날씨’, ‘춥네요’, ‘바람’, ‘감기’ all cluster around weather. Related expressions often signal the theme.", "freq": 2, "freqNote": "TOPIK I 듣기 9~12 · 주제 고르기", "audioHint": "남자: 날씨가 춥네요. 여자: 네, 바람도 불어요. 감기 조심하세요.", "id": "AII-b49da8"}, {"section": "reading", "type": "main_idea", "level": 3, "points": 2, "q": "이 글의 중심 생각으로 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate main idea of this passage.", "passage": "요즘 많은 직장인들이 점심 식사 후에 커피를 마신다. 그런데 커피 대신 짧은 산책을 하면 오후에 더 집중할 수 있다. 실제로 한 연구에 따르면 10분 정도 걸으면 머리가 맑아지고 피로가 줄어든다고 한다. 따라서 바쁘더라도 점심시간에 잠깐 밖에 나가는 것이 좋다.", "passageGl": "These days many office workers drink coffee after lunch. However, if they take a short walk instead of coffee, they can concentrate better in the afternoon. In fact, according to one study, walking for about 10 minutes clears the mind and reduces fatigue. Therefore, even if you are busy, it is good to go outside briefly during lunchtime.", "options": [{"t": "점심 식사 후 커피를 마시는 습관을 바꿔야 한다.", "gl": "We should change the habit of drinking coffee after lunch."}, {"t": "직장인들은 점심시간에 잠을 자야 한다.", "gl": "Office workers should sleep during lunchtime."}, {"t": "점심시간에 짧은 산책을 하면 오후 업무에 도움이 된다.", "gl": "Taking a short walk at lunchtime helps with afternoon work."}, {"t": "커피보다 산책이 건강에 더 나쁘다.", "gl": "Walking is worse for health than coffee."}], "correct": 2, "explain": "The passage contrasts drinking coffee with taking a short walk, cites research that walking clears the mind and reduces fatigue, and concludes that you should go outside briefly during lunch. This makes the benefit of a short lunchtime walk the central idea.", "traps": ["It overstates the passage by focusing on changing a coffee habit rather than on the recommended action.", "It introduces sleeping, which is never mentioned in the passage.", "It reverses the health comparison by saying walking is worse than coffee."], "tip": "For a main-idea question, look for the final recommendation or conclusion and check which option matches the repeated topic plus that conclusion.", "optExplain": ["오답: 커피 습관을 바꾸라는 내용은 글의 일부가 아니라 중심 생각이 아닙니다.", "오답: 점심시간에 잠을 자라는 내용은 글에 나오지 않습니다.", "정답: 짧은 산책이 오후 집중과 피로 감소에 도움이 된다는 내용이 글 전체에서 말하는 핵심입니다.", "오답: 산책이 커피보다 건강에 나쁘다는 것은 글의 내용과 반대입니다."], "optExplainEn": ["Wrong: Changing the coffee habit is not the central idea; it is only part of the passage.", "Wrong: Sleeping during lunchtime is never mentioned in the passage.", "Correct: The core message of the passage is that a short walk helps with afternoon concentration and reduces fatigue.", "Wrong: The claim that walking is worse for health than coffee contradicts the passage."], "tipEn": "For a main-idea question, look for the final recommendation or conclusion and check which option matches the repeated topic plus that conclusion.", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 중심 생각 고르기", "id": "AIII-b04d34"}, {"section": "reading", "type": "main_idea", "level": 3, "points": 2, "q": "이 글의 중심 내용으로 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate central content of this passage.", "passage": "우리 아파트 관리사무소에서는 다음 달부터 지하 주차장의 조명을 교체합니다. 공사 기간 동안 지하 주차장 일부 구역은 이용할 수 없으며, 차량은 지상 주차장을 이용해 주시기 바랍니다. 공사는 오전 9시부터 오후 6시까지 진행됩니다. 입주민 여러분의 양해를 부탁드립니다.", "passageGl": "Our apartment management office will replace the lighting in the underground parking lot starting next month. During the construction period, some areas of the underground parking lot will be unavailable, and vehicles should use the ground parking lot. The construction will take place from 9 a.m. to 6 p.m. We ask for residents' understanding.", "options": [{"t": "지하 주차장 조명 공사가 있어 지상 주차장을 이용해야 한다.", "gl": "Because of underground parking lot lighting construction, residents should use the ground parking lot."}, {"t": "아파트 지하 주차장을 새로 만든다.", "gl": "The apartment is building a new underground parking lot."}, {"t": "지상 주차장의 조명을 교체한다.", "gl": "The ground parking lot lighting will be replaced."}, {"t": "공사 기간 동안 지하 주차장을 무료로 이용할 수 있다.", "gl": "During construction, the underground parking lot can be used for free."}], "correct": 0, "explain": "The notice announces underground parking lighting replacement, states that some underground areas cannot be used during construction, and directs vehicles to the ground parking lot. This required action is the central content.", "traps": ["It introduces building a new underground parking lot, which is not mentioned.", "It incorrectly says the ground parking lot lighting will be replaced; the replacement is in the underground parking lot.", "It contradicts the notice by saying the underground parking lot can be used for free during construction."], "tip": "In announcement-type readings, identify who must do what. The correct main idea usually includes the requested action.", "optExplain": ["정답: 지하 주차장 조명 교체 공사로 일부 구역을 이용할 수 없어 지상 주차장을 이용하라는 안내가 중심 내용입니다.", "오답: 지하 주차장을 새로 만든다는 내용은 글에 없습니다.", "오답: 조명을 교체하는 곳은 지상이 아니라 지하 주차장입니다.", "오답: 공사 기간 동안 지하 주차장 일부 구역을 이용할 수 없으므로 무료 이용은 틀립니다."], "optExplainEn": ["Correct: The notice's central content is that some underground parking areas are closed due to lighting construction, so residents should use the ground parking lot.", "Wrong: Building a new underground parking lot is not mentioned in the passage.", "Wrong: The lighting being replaced is in the underground parking lot, not the ground parking lot.", "Wrong: Since some underground areas cannot be used during construction, free use is incorrect."], "tipEn": "In announcement-type readings, identify who must do what. The correct main idea usually includes the requested action.", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 중심 내용 고르기", "id": "AIII-917c61"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음 ( )에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "회사에 가는 길에 넘어져서 커피를 쏟을 ( ).", "passageGl": "On the way to work, I tripped and almost spilled my coffee.", "options": [{"t": "뻔했다", "gl": "almost did"}, {"t": "중이다", "gl": "in the middle of"}, {"t": "지 됐다", "gl": "has been since"}, {"t": "다가", "gl": "while doing and then"}], "correct": 0, "explain": "The sentence needs a grammar form meaning an action almost happened but did not actually happen. '-(으)ㄹ 뻔했다' expresses exactly that, so '커피를 쏟을 뻔했다' is natural.", "traps": ["'-는 중이다' indicates an action is in progress and would require '쏟는 중이다', not '쏟을 중이다'.", "'-(으)ㄴ 지' is used with time expressions like '몇 달이 됐다', so it does not fit.", "'-다가' indicates a change from one action to another, not an almost-happened event."], "tip": "For 'almost happened but did not' situations, use '-(으)ㄹ 뻔했다'. The preceding verb is in the future-modifier form.", "optExplain": ["정답: '-을 뻔했다'는 어떤 일이 거의 일어날 뻔했지만 실제로는 일어나지 않았음을 나타내므로 '커피를 쏟을 뻔했다'가 자연스럽습니다.", "오답: '-는 중이다'는 동작이 진행 중임을 나타내므로 '쏟는 중이다'가 되어야 자연스럽고 문맥에 맞지 않습니다.", "오답: '-(으)ㄴ 지'는 시간의 경과를 나타내므로 뒤에 '몇 달이 됐다' 같은 표현이 필요합니다.", "오답: '-다가'는 앞의 동작이 중단되고 다른 동작으로 바뀜을 나타내므로 어울리지 않습니다."], "optExplainEn": ["Correct: '-(으)ㄹ 뻔했다' expresses that an action almost happened but did not actually happen, so '커피를 쏟을 뻔했다' is natural.", "Wrong: '-는 중이다' indicates progressive action, so it would need to be '쏟는 중이다' and does not fit the context.", "Wrong: '-(으)ㄴ 지' indicates elapsed time and needs a phrase like '몇 달이 됐다' after it.", "Wrong: '-다가' indicates a shift from one action to another, so it is not suitable here."], "tipEn": "For 'almost happened but did not' situations, use '-(으)ㄹ 뻔했다'. The preceding verb is in the future-modifier form.", "freq": 2, "freqNote": "TOPIK II 읽기 1~4 · 문법 빈칸 채우기", "id": "AIII-130dfa"}, {"section": "reading", "type": "vocab", "level": 3, "points": 2, "q": "다음 ( )에 들어갈 가장 알맞은 것을 고르십시오.\n요즘 회사 일이 많아서 몸이 많이 ( ).", "qGl": "Choose the most appropriate word to fill in the blank.\nThese days I have a lot of work, so my body is very ___.", "passage": "", "passageGl": "", "options": [{"t": "지쳤다", "gl": "became tired"}, {"t": "늘었다", "gl": "increased"}, {"t": "모였다", "gl": "gathered"}, {"t": "나아졌다", "gl": "improved"}], "correct": 0, "explain": "The correct answer is '지쳤다' because it expresses becoming physically tired, matching the situation of having a lot of work.", "traps": ["'늘었다' means an increase in number, not a physical state, so it doesn’t fit '몸이 많이'.", "'모였다' means gathered, which cannot describe a body condition caused by work.", "'나아졌다' means improved, which contradicts the negative consequence of having too much work."], "tip": "For vocabulary fill-in-the-blank questions, read the whole sentence to identify the cause and result, then choose the word that logically completes the meaning.", "optExplain": ["정답: ‘지쳤다’는 몸이나 마음의 힘이 빠져 힘들어진 상태를 뜻해 일이 많아 몸이 힘들다는 문맥에 맞습니다.", "오답: ‘늘었다’는 수나 양이 많아졌다는 뜻으로 몸의 상태를 나타내기에 어색합니다.", "오답: ‘모였다’는 사람이나 사물이 한곳에 모인다는 뜻으로 문맥과 맞지 않습니다.", "오답: ‘나아졌다’는 상태가 좋아졌다는 뜻인데, 일이 많아서 힘들다는 원인과 결과가 어울리지 않습니다."], "optExplainEn": ["Correct: '지쳤다' means a state of being exhausted, which fits the context that the body is tired due to a lot of work.", "Wrong: '늘었다' means increased in number or amount, so it is awkward to describe physical condition.", "Wrong: '모였다' means gathered, which does not fit the context.", "Wrong: '나아졌다' means improved, but the cause-and-effect with being busy and tired does not match."], "tipEn": "For vocabulary fill-in-the-blank questions, read the whole sentence to identify the cause and result, then choose the word that logically completes the meaning.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 빈칸 어휘 고르기", "id": "AIII-021a04"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음 ( )에 들어갈 가장 알맞은 것을 고르십시오.\n비가 많이 와서 하마터면 약속에 늦을 ( ).", "qGl": "Choose the most appropriate grammar to fill in the blank.\nIt rained a lot, so I almost ___ late for the appointment.", "passage": "", "passageGl": "", "options": [{"t": "뻔했다", "gl": "almost did"}, {"t": "것 같다", "gl": "seems like"}, {"t": "수밖에 없다", "gl": "have no choice but to"}, {"t": "적이 없다", "gl": "have never done"}], "correct": 0, "explain": "The correct answer is '뻔했다' because it expresses that the speaker almost became late due to rain, which matches the adverb '하마터면'.", "traps": ["'것 같다' is for guessing, not for an event that nearly happened in the past.", "'수밖에 없다' is about unavoidable action, not about almost being late.", "'적이 없다' refers to lack of past experience, not a near miss."], "tip": "Remember that '하마터면' is often used with '-(으)ㄹ 뻔했다' to indicate a close call or near accident.", "optExplain": ["정답: '-(으)ㄹ 뻔했다'는 어떤 일이 실제로 일어나지는 않았지만 거의 일어날 정도였음을 나타내어 '하마터면'과 잘 어울립니다.", "오답: '-(으)ㄹ 것 같다'는 추측을 나타내므로 과거에 거의 늦었던 상황을 표현하기에는 어색합니다.", "오답: '-(으)ㄹ 수밖에 없다'는 다른 방법이 없음을 나타내므로 ‘하마터면’과 의미가 맞지 않습니다.", "오답: '-(으)ㄴ 적이 없다'는 과거의 경험이 없음을 나타내므로 문맥에 맞지 않습니다."], "optExplainEn": ["Correct: '-(으)ㄹ 뻔했다' expresses that something almost happened but did not actually happen, so it pairs naturally with '하마터면'.", "Wrong: '-(으)ㄹ 것 같다' indicates a guess or assumption, so it is awkward for describing a past situation that almost occurred.", "Wrong: '-(으)ㄹ 수밖에 없다' means having no choice but to do something, which does not fit with '하마터면'.", "Wrong: '-(으)ㄴ 적이 없다' means having never done something, which does not match the context."], "tipEn": "Remember that '하마터면' is often used with '-(으)ㄹ 뻔했다' to indicate a close call or near accident.", "freq": 2, "freqNote": "TOPIK II 읽기 3~4 · 빈칸 문법 고르기", "id": "AIII-92ec76"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 3, "q": "도서관을 이용할 수 없는 이유는 무엇입니까?", "qGl": "Why is the library unavailable?", "passage": "시립 도서관에서 알려 드립니다. 이번 주 토요일과 일요일에는 도서관 내부 공사가 진행됩니다. 공사 기간 중에는 책을 빌리거나 열람실을 이용할 수 없습니다. 이용에 불편을 드려 죄송합니다.", "passageGl": "The city library announces: This Saturday and Sunday, interior construction will take place. During the construction period, you cannot borrow books or use the reading rooms. We apologize for the inconvenience.", "options": [{"t": "도서관 내부 공사가 있기 때문이다", "gl": "Because there is interior construction"}, {"t": "새 책을 정리하고 있기 때문이다", "gl": "Because they are organizing new books"}, {"t": "도서관 직원 연수가 있기 때문이다", "gl": "Because there is staff training"}, {"t": "날씨가 좋지 않기 때문이다", "gl": "Because the weather is bad"}], "correct": 0, "explain": "The correct answer is 'interior construction' because the notice explicitly says the library cannot be used during the construction period.", "traps": ["'Organizing new books' is not mentioned in the passage.", "'Staff training' is not mentioned in the passage.", "'Bad weather' is not mentioned in the passage."], "tip": "In notice-type reading questions, look for time expressions and the main verb phrase (e.g., '이용할 수 없습니다') to identify the reason.", "optExplain": ["정답: 공사 기간 중에는 책을 빌리거나 열람실을 이용할 수 없다고 했으므로 도서관 내부 공사가 이용 불가의 원인입니다.", "오답: 새 책 정리에 대한 내용은 글에 전혀 언급되지 않았습니다.", "오답: 직원 연수에 대한 내용은 글에 전혀 언급되지 않았습니다.", "오답: 날씨에 대한 내용은 글에 전혀 언급되지 않았습니다."], "optExplainEn": ["Correct: The text states that during construction you cannot borrow books or use the reading rooms, so the interior construction is the reason.", "Wrong: Organizing new books is never mentioned in the passage.", "Wrong: Staff training is never mentioned in the passage.", "Wrong: Bad weather is never mentioned in the passage."], "tipEn": "In notice-type reading questions, look for time expressions and the main verb phrase (e.g., '이용할 수 없습니다') to identify the reason.", "freq": 2, "freqNote": "TOPIK II 읽기 9~12 · 짧은 안내문 이해", "id": "AIII-90e597"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate answer for the blank.", "passage": "영수는 회사에 (      ) 3년이 되었다.", "passageGl": "Youngsu has been working at the company for 3 years.", "options": [{"t": "다닌 지", "gl": "since he started working"}, {"t": "다니는 데다가", "gl": "in addition to working"}, {"t": "다닌 척", "gl": "pretending to work"}, {"t": "다닐 뻔했다", "gl": "almost went to work"}], "correct": 0, "explain": "The grammar pattern '-(으)ㄴ 지' is used to express the amount of time that has passed since an action happened. In this sentence, '다닌 지 3년이 되었다' means it has been three years since he started working at the company.", "traps": ["'-는 데다가' means 'in addition to' and does not fit with a time expression like '3년이 되었다'.", "'-ㄴ 척' means 'pretending to do' and would create an illogical meaning: 'pretending to work for 3 years'.", "'-ㄹ 뻔했다' means 'almost did' and cannot be used with a current state of three years having passed."], "tip": "Remember that '-(으)ㄴ 지' is always followed by a time phrase such as '3년이 되었다' or '한 달이 지났다'.", "optExplain": ["정답: '다닌 지'는 어떤 일이 일어난 후 지난 시간을 나타내는 '-(으)ㄴ 지' 표현으로, 회사에 다니기 시작한 지 3년이 되었다는 뜻이 되어 자연스럽습니다.", "오답: '다니는 데다가'는 '~하는 것에 더하여'라는 뜻이므로 시간 표현과 어울리지 않습니다.", "오답: '다닌 척'은 '다니는 것처럼 꾸미다'라는 뜻이 되어 문장 의미가 이상해집니다.", "오답: '다닐 뻔했다'는 '거의 다닐 뻔했다'는 뜻으로, 이미 3년이 지난 현재 상태를 나타낼 수 없습니다."], "optExplainEn": ["Correct: '다닌 지' uses the pattern '-(으)ㄴ 지' which expresses the time that has passed since an action occurred, so the sentence naturally means it has been three years since he started working at the company.", "Wrong: '다니는 데다가' means 'in addition to doing' and does not fit with a time expression.", "Wrong: '다닌 척' would mean 'pretending to go to work', making the sentence illogical.", "Wrong: '다닐 뻔했다' means 'almost went to work' and cannot describe a current state after three years have passed."], "tipEn": "Remember that '-(으)ㄴ 지' is always followed by a time phrase such as '3년이 되었다' or '한 달이 지났다'.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 문법", "id": "AIII-186268"}, {"section": "reading", "type": "vocab", "level": 3, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate answer for the blank.", "passage": "회의에서 의견이 서로 달라서 (      )이/가 생겼다.", "passageGl": "At the meeting, opinions differed, so a conflict arose.", "options": [{"t": "갈등", "gl": "conflict"}, {"t": "참석", "gl": "attendance"}, {"t": "예산", "gl": "budget"}, {"t": "휴가", "gl": "vacation"}], "correct": 0, "explain": "The sentence describes a situation where opinions differ, which naturally leads to '갈등' (conflict). The other words do not fit the context of disagreement.", "traps": ["'참석' means attendance and refers to being present, not a result of differing opinions.", "'예산' means budget, which is unrelated to the disagreement in the meeting.", "'휴가' means vacation, which does not logically follow from differing opinions at a meeting."], "tip": "Learn common abstract nouns like '갈등' (conflict), '의견' (opinion), and '예산' (budget) because they often appear in reading passages about work and society.", "optExplain": ["정답: '갈등'은 서로 생각이 달라서 생기는 충돌을 뜻하므로 회의에서 의견이 다르다는 내용과 자연스럽게 연결됩니다.", "오답: '참석'은 '모임에 참여함'을 뜻하는 말로, 의견 차이로 생기는 결과와 어울리지 않습니다.", "오답: '예산'은 돈이나 비용에 관련된 단어이므로 의견이 다르다는 내용과 관련이 없습니다.", "오답: '휴가'는 쉬는 기간을 뜻하는 단어로, 회의에서 의견이 다르다는 상황과 연결되지 않습니다."], "optExplainEn": ["Correct: '갈등' means a clash caused by different opinions, so it naturally fits the context of differing opinions at a meeting.", "Wrong: '참석' means attendance or being present, which is not a result of differing opinions.", "Wrong: '예산' means budget, which is unrelated to the disagreement in the meeting.", "Wrong: '휴가' means vacation, which does not logically follow from differing opinions at a meeting."], "tipEn": "Learn common abstract nouns like '갈등' (conflict), '의견' (opinion), and '예산' (budget) because they often appear in reading passages about work and society.", "freq": 2, "freqNote": "TOPIK II 읽기 3~4 · 어휘", "id": "AIII-ca43f8"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 2, "q": "윗글의 내용과 같은 것을 고르십시오.", "qGl": "Choose the statement that matches the content of the passage.", "passage": "요즘 많은 사람들이 건강을 지키기 위해 규칙적으로 운동을 하고 있다. 하지만 운동을 처음 시작하는 사람들은 무리하게 운동을 해서 오히려 몸을 다치기도 한다. 전문가들은 자신의 체력에 맞는 운동을 선택하고 충분한 휴식을 취하는 것이 중요하다고 말한다.", "passageGl": "These days, many people exercise regularly to stay healthy. However, people who are new to exercise sometimes overdo it and get injured. Experts say it is important to choose an exercise that fits one's physical strength and to get enough rest.", "options": [{"t": "운동을 하면 누구나 부상을 입는다.", "gl": "Everyone who exercises gets injured."}, {"t": "자신의 체력에 맞는 운동을 하는 것이 좋다.", "gl": "It is good to do exercise that fits one's physical strength."}, {"t": "건강을 위해 운동을 하지 않는 것이 낫다.", "gl": "It is better not to exercise for health."}, {"t": "운동을 시작하면 몸을 다치지 않는다.", "gl": "If you start exercising, you will not get injured."}], "correct": 1, "explain": "The passage says experts recommend choosing an exercise that fits one's physical strength and taking enough rest, so option 1 matches the content. The other options are not supported by the text.", "traps": ["Option 0 says everyone who exercises gets injured, but the passage says people who overdo it may get injured, not everyone.", "Option 2 says it is better not to exercise, but the passage states many people exercise to stay healthy and experts only advise doing it safely.", "Option 3 says starting exercise prevents injury, which is the opposite of the passage's warning about overdoing it."], "tip": "For 'choose the same content' questions, compare each option with the passage word by word and avoid extreme words like '누구나' (everyone) or '절대로' (never).", "optExplain": ["정답: 지문에서 전문가들이 체력에 맞는 운동을 선택하라고 했으므로 '자신의 체력에 맞는 운동을 하는 것이 좋다'는 내용과 일치합니다.", "오답: 지문은 무리한 운동을 할 때 부상을 입을 수 있다고 했지, 운동을 하면 누구나 부상을 입는다고 하지 않았습니다.", "오답: 지문은 운동을 하지 말라고 하지 않고 안전하게 운동하라고 했으므로 '운동을 하지 않는 것이 낫다'는 내용과 다릅니다.", "오답: 지문은 처음 운동을 시작하는 사람도 무리하면 다칠 수 있다고 했으므로 '운동을 시작하면 다치지 않는다'는 내용과 반대입니다."], "optExplainEn": ["Correct: The passage says experts advise choosing exercise that fits one's physical strength, so 'It is good to do exercise that fits one's physical strength' matches the content.", "Wrong: The passage says people may get injured if they overdo exercise, not that everyone who exercises gets injured.", "Wrong: The passage does not say not to exercise; rather it advises exercising safely, so 'It is better not to exercise' is different.", "Wrong: The passage warns that beginners can get injured if they overdo it, so 'If you start exercising, you will not get injured' is opposite to the text."], "tipEn": "For 'choose the same content' questions, compare each option with the passage word by word and avoid extreme words like '누구나' (everyone) or '절대로' (never).", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 내용 일치", "id": "AIII-ae34b2"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 2, "q": "윗글의 내용과 같은 것을 고르십시오.", "qGl": "Choose the statement that matches the passage.", "passage": "최근 직장인들 사이에서 혼자 점심을 먹는 사람이 늘고 있다. 바쁜 업무 때문에 동료와 시간을 맞추기가 어려워졌기 때문이다. 혼자 먹으면 시간을 아낄 수 있고 편하다는 장점이 있다. 하지만 같이 먹으며 나누는 대화가 줄어들면서 동료들과의 관계가 멀어질 수 있다는 걱정도 나온다.", "passageGl": "Recently, the number of office workers who eat lunch alone is increasing. This is because busy work has made it difficult to match schedules with colleagues. Eating alone has the advantage of saving time and being comfortable. However, as conversations shared while eating together decrease, there is also concern that relationships with colleagues may grow distant.", "options": [{"t": "직장인들은 예전부터 혼자 점심을 먹었다.", "gl": "Office workers have always eaten lunch alone."}, {"t": "바쁜 업무 때문에 혼자 먹는 사람이 늘었다.", "gl": "More people eat alone because of busy work."}, {"t": "혼자 점심을 먹으면 동료와 대화가 늘어난다.", "gl": "Eating lunch alone increases conversation with colleagues."}, {"t": "동료와의 관계가 가까워질까 봐 걱정한다.", "gl": "They worry that relationships with colleagues will get closer."}], "correct": 1, "explain": "The passage states that '바쁜 업무 때문에 동료와 시간을 맞추기가 어려워졌기 때문이다' and that '혼자 점심을 먹는 사람이 늘고 있다.' Therefore, the correct answer is that more people are eating alone because of busy work.", "traps": ["Option 1 is wrong: the passage says this is a recent trend, not something that has always happened.", "Option 3 reverses the passage: eating alone reduces conversation, not increases it.", "Option 4 is wrong: the concern is that relationships may become distant, not closer."], "tip": "For content-matching questions, compare each option against the passage sentence by sentence. Watch for words that changed meaning, such as '늘어난다' vs '줄어든다' or '가까워질까' vs '멀어질 수 있다'.", "optExplain": ["오답: 이 글은 혼자 점심을 먹는 사람이 최근에 늘고 있다고 했으므로 예전부터 그랬다는 것은 글의 내용과 다릅니다.", "정답: 바쁜 업무 때문에 동료와 시간을 맞추기 어려워져서 혼자 점심을 먹는 사람이 늘었다고 했으므로 글의 내용과 같습니다.", "오답: 혼자 먹으면 같이 먹으며 나누는 대화가 줄어든다고 했으므로 대화가 늘어난다는 것은 틀립니다.", "오답: 동료들과의 관계가 멀어질 수 있다는 걱정이 나온다고 했으므로 가까워질까 봐 걱정한다는 것은 틀립니다."], "optExplainEn": ["Wrong: The passage says people eating lunch alone have recently increased, so saying it has always been that way does not match.", "Correct: The passage says that because busy work makes it hard to match schedules with colleagues, more people eat lunch alone, so this matches.", "Wrong: The passage says conversations shared while eating together decrease, so saying conversation increases is incorrect.", "Wrong: The passage mentions concern that relationships may grow distant, so worrying they will get closer is incorrect."], "tipEn": "For content-matching questions, compare each option against the passage sentence by sentence. Watch for words that changed meaning, such as '늘어난다' vs '줄어든다' or '가까워질까' vs '멀어질 수 있다'.", "freq": 2, "freqNote": "TOPIK II 읽기 16~18 · 내용 일치", "id": "AIII-741421"}, {"section": "listening", "type": "grammar", "level": 3, "points": 2, "q": "가: 어제 도서관에서 공부하다가 갑자기 코피가 나서 화장실로 뛰어갔어요. 나: 괜찮았어요? 요즘 너무 무리했나 봐요. 질문: 들은 내용과 같은 것을 고르십시오.", "qGl": "A: Yesterday, while studying at the library, I suddenly got a nosebleed and ran to the bathroom. B: Were you okay? You seem to have overdone it lately. Question: Choose the statement that matches what you heard.", "passage": "", "passageGl": "", "audioHint": "도서관에서 공부하다가 갑자기 코피가 나서 화장실로 뛰어갔다.", "options": [{"t": "도서관에서 계속 공부했다.", "gl": "He kept studying at the library."}, {"t": "공부하다가 코피가 나서 화장실로 뛰어갔다.", "gl": "He was studying when he got a nosebleed and ran to the bathroom."}, {"t": "코피가 나서 병원에 입원했다.", "gl": "He got a nosebleed and was hospitalized."}, {"t": "공부를 하지 않고 집에 있었다.", "gl": "He stayed home without studying."}], "correct": 1, "explain": "The dialogue says the man was studying at the library, suddenly got a nosebleed, and ran to the bathroom. This matches the grammar -다가, which shows an action interrupted by another event.", "traps": ["It ignores the interruption caused by the nosebleed.", "It adds hospitalization, which was not mentioned.", "It contradicts the fact that he went to the library."], "tip": "Listen for -다가; it signals that an action stopped or changed because of a new event.", "optExplain": ["오답: 남자는 공부를 계속하지 않고 코피가 나서 중단했습니다.", "정답: 남자가 도서관에서 공부하다가 코피가 나서 화장실로 뛰어갔다고 했습니다.", "오답: 병원에 입원했다는 내용은 대화에 없습니다.", "오답: 남자는 도서관에 갔으므로 집에 있었다는 말과 다릅니다."], "optExplainEn": ["Wrong: The man did not keep studying; he stopped because of a nosebleed.", "Correct: The man was studying at the library when he got a nosebleed and ran to the bathroom.", "Wrong: Hospitalization is not mentioned in the dialogue.", "Wrong: He went to the library, so this contradicts staying home."], "tipEn": "Listen for -다가; it signals that an action stopped or changed because of a new event.", "freq": 2, "freqNote": "TOPIK II 듣기 10~12 · 짧은 대화 세부 내용 파악", "id": "AIII-d055d7"}, {"section": "listening", "type": "topic", "level": 3, "points": 2, "q": "가: 다음 주부터 새로 시작하는 프로젝트 때문에 요즘 계속 야근이에요. 나: 저도 마감이 얼마 안 남아서 주말에도 출근해야 할 것 같아요. 가: 팀원들끼리 역할을 나누면 좀 나아질까요? 나: 그래도 일정이 빠듯해서 쉽지 않을 거예요. 질문: 무엇에 대해 이야기하고 있습니까?", "qGl": "A: I've been working late every day because of the new project starting next week. B: Me too. The deadline is near, so I'll probably have to go to work on the weekend. A: Would it get better if we divide roles among team members? B: Still, the schedule is tight, so it won't be easy. Question: What are they talking about?", "passage": "", "passageGl": "", "audioHint": "야근과 주말 출근 때문에 일이 많아 힘들다는 이야기.", "options": [{"t": "주말 여행 계획", "gl": "Weekend travel plans"}, {"t": "새 프로젝트 팀원 소개", "gl": "Introducing new project team members"}, {"t": "일이 많아서 힘든 상황", "gl": "A difficult situation due to heavy workload"}, {"t": "회사 근처 식당 추천", "gl": "Recommending a restaurant near work"}], "correct": 2, "explain": "The two speakers repeatedly mention overtime, weekend work, deadlines, and a tight schedule. The overall topic is how they are struggling with a heavy workload.", "traps": ["The dialogue is not about making travel plans.", "It is not introducing team members; it is about work pressure.", "No restaurant recommendation appears at all."], "tip": "In topic questions, listen for repeated words like 야근, 출근, 일정, 마감. Focus on the overall situation rather than one word.", "optExplain": ["오답: 여행 계획을 정하는 내용이 아닙니다.", "오답: 팀원 소개가 아니라 업무 부담에 대한 이야기입니다.", "정답: 야근과 주말 출근을 말하며 일이 많아 힘들다는 상황을 이야기하고 있습니다.", "오답: 식당 추천은 전혀 나오지 않았습니다."], "optExplainEn": ["Wrong: They are not planning a trip.", "Wrong: They are not introducing team members; they are talking about workload.", "Correct: They mention overtime and weekend work, showing a difficult workload situation.", "Wrong: There is no restaurant recommendation."], "tipEn": "In topic questions, listen for repeated words like overtime, going to work, schedule, and deadline. Focus on the overall situation rather than one word.", "freq": 2, "freqNote": "TOPIK II 듣기 4~6 · 대화 주제 파악", "id": "AIII-39f1c8"}, {"section": "listening", "type": "comprehension", "level": 3, "points": 2, "q": "가: 이번 주말에 같이 등산 갈래요? 날씨가 좋을 것 같아요. 나: 좋아요. 그런데 저는 등산화가 없어서 불편할 것 같아요. 가: 괜찮아요. 제가 여분 등산화를 하나 빌려 드릴 수 있어요. 나: 정말요? 그럼 등산 초보인 저도 편하게 다녀올 수 있겠네요. 가: 네, 등산로도 쉬운 코스로 정할게요. 질문: 여자가 이번 주말에 무엇을 할 것입니까?", "qGl": "A: Do you want to go hiking together this weekend? The weather looks nice. B: Sure, but I don't have hiking boots, so I might be uncomfortable. A: That's okay. I can lend you an extra pair of hiking boots. B: Really? Then even a beginner like me can go comfortably. A: Yes, and I'll pick an easy trail too. Question: What will the woman do this weekend?", "passage": "", "passageGl": "", "audioHint": "주말에 여자가 남자와 함께 등산을 가기로 했다.", "options": [{"t": "등산화를 사러 갈 것이다.", "gl": "She will go to buy hiking boots."}, {"t": "남자와 함께 등산을 갈 것이다.", "gl": "She will go hiking with the man."}, {"t": "등산 대신 영화를 볼 것이다.", "gl": "She will watch a movie instead of hiking."}, {"t": "집에서 쉴 것이다.", "gl": "She will rest at home."}], "correct": 1, "explain": "The woman agrees to go hiking with the man. She does not buy boots; the man offers to lend her an extra pair, and he says he will choose an easy trail.", "traps": ["She is not buying hiking boots; she will borrow them.", "Watching a movie is never mentioned.", "She is not staying home; she agreed to go hiking."], "tip": "For detail questions, note who offers help and what is finally decided. The final decision usually determines the answer.", "optExplain": ["오답: 등산화를 사는 것이 아니라 남자에게 빌린다고 했습니다.", "정답: 여자가 등산화를 빌리고 남자와 함께 등산을 가기로 했습니다.", "오답: 영화를 보자는 말은 나오지 않았습니다.", "오답: 집에서 쉰다는 말은 없고 주말에 등산을 가기로 했습니다."], "optExplainEn": ["Wrong: She will borrow hiking boots, not buy them.", "Correct: The woman will borrow hiking boots and go hiking with the man.", "Wrong: Watching a movie is not mentioned.", "Wrong: She is not staying home; she agreed to go hiking."], "tipEn": "For detail questions, note who offers help and what is finally decided. The final decision usually determines the answer.", "freq": 2, "freqNote": "TOPIK II 듣기 13~15 · 대화 후 할 일/상황 파악", "id": "AIII-c7ec65"}, {"section": "listening", "type": "grammar", "level": 3, "points": 3, "q": "여자: 요즘 밤마다 잠을 잘 못 자서 회사에서 계속 졸려요.\n남자: 이번 주말에는 푹 쉬었으면 좋겠어요.\n질문: 남자의 말에 나타난 마음으로 알맞은 것을 고르십시오.", "qGl": "Woman: Lately I can't sleep well at night, so I keep feeling sleepy at work.\nMan: I hope you can rest well this weekend.\nQuestion: Choose the feeling shown in the man's words.", "passage": "", "passageGl": "", "audioHint": "여자: 요즘 잠을 못 자서 계속 졸려요.\n남자: 주말에는 푹 쉬었으면 좋겠어요.", "options": [{"t": "바람", "gl": "wish/hope"}, {"t": "후회", "gl": "regret"}, {"t": "계획", "gl": "plan"}, {"t": "습관", "gl": "habit"}], "correct": 0, "explain": "The man says '이번 주말에는 푹 쉬었으면 좋겠어요,' using the grammar -았/었으면 좋겠다, which expresses a hope or wish. He is not expressing regret, making a plan, or describing a habit.", "traps": ["후회(regret) refers to feeling sorry about the past, not hoping for future rest.", "계획(plan) implies a fixed arrangement, but the man is only expressing a wish.", "습관(habit) means a repeated behavior, which does not match the one-time wish."], "tip": "Study the pattern '-았/었으면 좋겠다' as a way to express wishes or hopes; it often appears in listening questions about a speaker's emotional state or intention.", "optExplain": ["정답: '-았/었으면 좋겠다'는 어떤 일이 이루어지기를 바라는 마음을 나타내므로 '바람'이 맞습니다.", "오답: '후회'는 이미 지나간 일에 대해 아쉬워하는 마음이므로 대화와 어울리지 않습니다.", "오답: '계획'은 앞으로 할 일을 미리 정하는 것이므로 '기대'나 '소망'과는 다릅니다.", "오답: '습관'은 반복적인 행동을 뜻하므로 이 말에 해당하지 않습니다."], "optExplainEn": ["Correct: '-았/었으면 좋겠다' expresses a wish, so 'wish/hope' is correct.", "Wrong: 'Regret' is about feeling sorry for the past, which does not fit the dialogue.", "Wrong: 'Plan' means a fixed intention, not a wish or hope.", "Wrong: 'Habit' refers to repeated behavior, not the man's one-time wish."], "tipEn": "Study the pattern '-았/었으면 좋겠다' as a way to express wishes or hopes; it often appears in listening questions about a speaker's emotional state or intention.", "freq": 2, "freqNote": "TOPIK II 듣기 16~20 · 대화 속 표현의 의미", "id": "AIII-dafaf0"}, {"section": "listening", "type": "intent", "level": 3, "points": 3, "q": "여자: 주말인데 어디에 가려고?\n남자: 도서관에 가서 다음 주 시험 준비를 좀 하려고요.\n여자: 그럼 밥은 언제 먹을 거야?\n남자: 도서관 앞 식당에서 간단히 먹을게요.\n질문: 남자가 지금 하려는 일로 알맞은 것을 고르십시오.", "qGl": "Woman: It's the weekend, so where are you going?\nMan: I'm going to the library to prepare for next week's exam.\nWoman: Then when will you eat?\nMan: I'll eat simply at the restaurant in front of the library.\nQuestion: Choose what the man is trying to do now.", "passage": "", "passageGl": "", "audioHint": "여자: 주말인데 어디에 가려고?\n남자: 도서관에서 시험 준비를 하려고요.", "options": [{"t": "시험을 준비하려고 한다", "gl": "to prepare for an exam"}, {"t": "도서관에서 책을 빌리려고 한다", "gl": "to borrow a book from the library"}, {"t": "주말에 여행을 가려고 한다", "gl": "to go on a trip on the weekend"}, {"t": "식당에서 아르바이트를 하려고 한다", "gl": "to work part-time at a restaurant"}], "correct": 0, "explain": "The man clearly states he is going to the library to prepare for next week's exam. The other actions—borrowing a book, traveling, or working part-time—are not mentioned.", "traps": ["Borrowing a book is a possible library activity but is not stated.", "Traveling is not mentioned at all in the dialogue.", "The restaurant is only where he will eat; there is no mention of a part-time job."], "tip": "Listen carefully for '-려고요' and '-려고 하다' because they signal the speaker's intention or immediate plan.", "optExplain": ["정답: 남자가 도서관에 가서 다음 주 시험 준비를 하려고 했으므로 '시험을 준비하려고 한다'가 맞습니다.", "오답: 책을 빌린다는 내용은 대화에 나오지 않습니다.", "오답: 여행에 대한 언급은 전혀 없습니다.", "오답: 식당은 밥을 먹는 장소일 뿐 아르바이트 계획은 없습니다."], "optExplainEn": ["Correct: The man says he is going to prepare for next week's exam, so this is correct.", "Wrong: Borrowing a book is not mentioned.", "Wrong: Traveling is not mentioned.", "Wrong: The restaurant is only a place to eat, not a part-time job."], "tipEn": "Listen carefully for '-려고요' and '-려고 하다' because they signal the speaker's intention or immediate plan.", "freq": 2, "freqNote": "TOPIK II 듣기 9~12 · 화자의 의도 파악", "id": "AIII-4578d0"}, {"section": "listening", "type": "intent", "level": 3, "points": 3, "q": "여자: 방학에 뭐 할 거예요?\n남자: 한국어를 배우려고 어학당에 다닐 생각이에요.\n여자: 그래서 저번에 한국어 책을 산 거군요.\n남자: 네, 미리 공부해 놓으려고요.\n질문: 남자가 방학에 하려는 일로 알맞은 것을 고르십시오.", "qGl": "Woman: What will you do during the vacation?\nMan: I'm planning to attend a language school to learn Korean.\nWoman: So that's why you bought a Korean book the other day.\nMan: Yes, I wanted to study in advance.\nQuestion: Choose what the man plans to do during the vacation.", "passage": "", "passageGl": "", "audioHint": "남자: 방학에 한국어를 배우려고 어학당에 다닐 생각이에요.\n여자: 그래서 한국어 책을 샀군요.", "options": [{"t": "한국어를 배우려고 한다", "gl": "to learn Korean"}, {"t": "한국에 취직하려고 한다", "gl": "to get a job in Korea"}, {"t": "책을 쓰려고 한다", "gl": "to write a book"}, {"t": "어학당에서 가르치려고 한다", "gl": "to teach at a language school"}], "correct": 0, "explain": "The man says he plans to attend a language school to learn Korean and bought a Korean book to study in advance. Therefore his intended action is learning Korean.", "traps": ["Getting a job in Korea is not mentioned.", "Writing a book is not mentioned.", "He wants to learn, not teach, at the language school."], "tip": "For intention questions, focus on expressions like '-(으)려고', '-ㄹ 생각이다', and '-아/어 놓다' to identify what the speaker plans to do.", "optExplain": ["정답: 남자가 '한국어를 배우려고 어학당에 다닐 생각이에요'라고 했으므로 '한국어를 배우려고 한다'가 맞습니다.", "오답: 한국 취직에 대한 내용은 대화에 나오지 않습니다.", "오답: 책을 쓴다는 내용은 대화에 나오지 않습니다.", "오답: 남자는 어학당에서 배우려는 것이지 가르치려는 것이 아닙니다."], "optExplainEn": ["Correct: The man says he plans to attend a language school to learn Korean, so this is correct.", "Wrong: Getting a job in Korea is not mentioned.", "Wrong: Writing a book is not mentioned.", "Wrong: The man wants to learn, not teach, at the language school."], "tipEn": "For intention questions, focus on expressions like '-(으)려고', '-ㄹ 생각이다', and '-아/어 놓다' to identify what the speaker plans to do.", "freq": 2, "freqNote": "TOPIK II 듣기 9~12 · 화자의 의도 파악", "id": "AIII-48a4d4"}, {"section": "listening", "type": "place", "level": 3, "points": 3, "q": "가: 이번 주말에 등산 갈까요? 나: 좋아요. 그런데 날씨가 추우니까 옷을 따뜻하게 입으세요. 가: 네, 장갑이랑 목도리도 챙길게요. 나: 그럼 주말 아침에 산 입구에서 만나요. 가: 알겠습니다. 그때 봐요. 질문: 두 사람이 주말에 만날 장소는 어디입니까?", "qGl": "A: Shall we go hiking this weekend? B: Sure. But since it's cold, please dress warmly. A: Okay, I'll bring gloves and a scarf. B: Then let's meet at the mountain entrance on weekend morning. A: Got it. See you then. Question: Where will the two people meet on the weekend?", "passage": "", "passageGl": "", "options": [{"t": "산 입구", "gl": "mountain entrance"}, {"t": "산 정상", "gl": "mountain top"}, {"t": "회사 정문", "gl": "company main gate"}, {"t": "버스 터미널", "gl": "bus terminal"}], "correct": 0, "explain": "The male speaker explicitly says '산 입구에서 만나요' (Let's meet at the mountain entrance). Therefore, the meeting place is the mountain entrance.", "traps": ["Mountain top is not mentioned as the meeting place; it is a similar-sounding location but not what was said.", "The company gate is unrelated to the weekend hiking meeting.", "The bus terminal is not mentioned at all in the dialogue."], "tip": "장소 고르기 문제에서는 대화 속 장소 명사를 놓치지 말고, '어디에서 만나요'와 같은 표현 뒤에 나오는 장소에 집중하세요.", "optExplain": ["정답: 남자가 '산 입구에서 만나요'라고 했으므로 만날 장소는 산 입구입니다.", "오답: 산 정상은 대화에 나오지 않았고, 만날 장소로 언급되지 않았습니다.", "오답: 회사 정문은 두 사람이 주말에 만날 장소와 관련이 없습니다.", "오답: 버스 터미널은 대화에 나오지 않았습니다."], "optExplainEn": ["Correct: The man says 'Let's meet at the mountain entrance,' so the meeting place is the mountain entrance.", "Wrong: The mountain top is not mentioned in the dialogue as the meeting place.", "Wrong: The company main gate is not related to the weekend meeting place.", "Wrong: The bus terminal is not mentioned in the dialogue."], "tipEn": "In place questions, don't miss the location nouns in the dialogue. Focus on the place that follows expressions like '어디에서 만나요'.", "freq": 2, "freqNote": "TOPIK II 듣기 1~3 · 장소 고르기", "audioHint": "가: 이번 주말에 등산 갈까요? 나: 좋아요. 그럼 주말 아침에 산 입구에서 만나요.", "id": "AIII-0843c2"}, {"section": "listening", "type": "grammar", "level": 3, "points": 3, "q": "가: 이번 주말에 같이 영화 볼래요? 나: 미안해요. 요즘 일이 너무 많아서 야근을 할 수밖에 없어요. 질문: 여자의 말의 의미로 알맞은 것을 고르십시오.", "qGl": "A: Do you want to see a movie with me this weekend? B: Sorry, I have so much work these days that I have no choice but to work overtime. Question: Choose the option that best expresses the woman's meaning.", "passage": "", "passageGl": "", "options": [{"t": "영화를 보러 갈 수 있다.", "gl": "She can go see a movie."}, {"t": "야근을 하지 않아도 된다.", "gl": "She doesn't have to work overtime."}, {"t": "야근을 반드시 해야 한다.", "gl": "She has no choice but to work overtime."}, {"t": "일이 벌써 끝났다.", "gl": "The work is already finished."}], "correct": 2, "explain": "The woman uses '-(으)ㄹ 수밖에 없다', which expresses an unavoidable obligation or no choice. Because she has too much work, she must work overtime.", "traps": ["She says she cannot go to the movie, not that she can.", "The grammar implies obligation, not permission to skip work.", "The dialogue does not say the work is already finished; she says she has to work overtime."], "tip": "청취에서 문법 표현이 들리면 그 의미를 바로 연결하세요. '-(으)ㄹ 수밖에 없다'는 '반드시 ~해야 한다'로 바꿔 이해하면 쉽습니다.", "optExplain": ["오답: 여자는 주말에 영화를 볼 수 있다고 말하지 않았습니다.", "오답: 여자는 야근을 하지 않아도 된다고 말하지 않았습니다.", "정답: ‘-(으)ㄹ 수밖에 없다’는 반드시 해야 한다는 뜻이므로 야근을 반드시 해야 한다는 의미입니다.", "오답: 일이 끝났다는 내용은 대화에 나오지 않았습니다."], "optExplainEn": ["Wrong: The woman did not say she can see a movie on the weekend.", "Wrong: The woman did not say she doesn't have to work overtime.", "Correct: The expression '-(으)ㄹ 수밖에 없다' means 'have no choice but to', so she must work overtime.", "Wrong: The dialogue does not say the work is already finished."], "tipEn": "When you hear a grammar expression, connect its meaning immediately. '-(으)ㄹ 수밖에 없다' can be understood as 'must do'.", "freq": 2, "freqNote": "TOPIK II 듣기 4~6 · 문법 표현 고르기", "audioHint": "가: 주말에 영화 볼래요? 나: 미안해요. 일이 많아서 야근을 할 수밖에 없어요.", "id": "AIII-4b2f08"}, {"section": "reading", "type": "vocab", "level": 1, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "저는 주말에 친구와 영화를 ____.", "passageGl": "I ____ a movie with a friend on the weekend.", "options": [{"t": "봐요", "gl": "watch"}, {"t": "먹어요", "gl": "eat"}, {"t": "입어요", "gl": "wear"}, {"t": "자요", "gl": "sleep"}], "correct": 0, "explain": "The correct answer is '봐요' because the verb '보다 (to see/watch)' collocates with '영화를 (a movie)' to mean 'watch a movie'.", "traps": ["'먹어요' means 'eat', which is used with food, not movies.", "'입어요' means 'wear', which is used with clothes, not movies.", "'자요' means 'sleep', which cannot be used with '영화를'."], "tip": "Memorize common verb-object collocations such as 영화를 보다, 밥을 먹다, 옷을 입다, 잠을 자다.", "optExplain": ["정답: ‘영화를 보다’가 자연스러운 표현이에요.", "오답: ‘먹어요’는 음식을 먹을 때 쓰는 말이에요.", "오답: ‘입어요’는 옷을 입을 때 쓰는 말이에요.", "오답: ‘자요’는 잠을 잘 때 쓰는 말이에요."], "optExplainEn": ["Correct: '영화를 보다' is a natural expression.", "Wrong: '먹어요' is used when eating food.", "Wrong: '입어요' is used when wearing clothes.", "Wrong: '자요' is used when sleeping."], "tipEn": "Memorize common verb-object collocations such as 영화를 보다, 밥을 먹다, 옷을 입다, 잠을 자다.", "freq": 2, "freqNote": "TOPIK I 읽기 8~10 · 빈칸 채우기", "id": "AII-2ccaef"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "다음을 읽고 내용과 같은 것을 고르십시오.", "qGl": "Read the following and choose the one that matches the content.", "passage": "다음 주 월요일은 학교 생일입니다. 친구들과 같이 교실에서 작은 파티를 합니다. 우리는 케이크와 음료수를 준비합니다.", "passageGl": "Next Monday is the school's birthday. We will have a small party in the classroom with friends. We prepare cake and drinks.", "options": [{"t": "파티는 집에서 합니다.", "gl": "The party is held at home."}, {"t": "파티는 다음 주 월요일에 합니다.", "gl": "The party is held next Monday."}, {"t": "케이크를 준비하지 않습니다.", "gl": "We do not prepare a cake."}, {"t": "친구들과 파티를 안 합니다.", "gl": "We do not have a party with friends."}], "correct": 1, "explain": "The passage says '다음 주 월요일은 학교 생일입니다' and '작은 파티를 합니다', so the party is next Monday. The other choices contradict the passage.", "traps": ["'집에서 합니다' is wrong because the passage says '교실에서'.", "'케이크를 준비하지 않습니다' is wrong because the passage says they prepare cake.", "'친구들과 파티를 안 합니다' is wrong because the passage says they have a party with friends."], "tip": "For comprehension questions, compare each option with the exact words in the passage. Look for words like place, time, and whether an action happens or not.", "optExplain": ["오답: 글에서 파티는 ‘집’이 아니라 ‘교실’에서 한다고 했어요.", "정답: 글에서 ‘다음 주 월요일’에 ‘파티를 합니다’라고 했어요.", "오답: 글에서 케이크를 ‘준비합니다’라고 했어요.", "오답: 글에서 친구들과 ‘같이’ 파티를 한다고 했어요."], "optExplainEn": ["Wrong: The passage says the party is held in the classroom, not at home.", "Correct: The passage says the party is held 'next Monday'.", "Wrong: The passage says they prepare a cake.", "Wrong: The passage says they have a party together with friends."], "tipEn": "For comprehension questions, compare each option with the exact words in the passage. Look for words like place, time, and whether an action happens or not.", "freq": 2, "freqNote": "TOPIK I 읽기 16~18 · 짧은 글 이해", "id": "AII-fb1fab"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "다음을 읽고 내용과 같은 것을 고르십시오.", "qGl": "Read the following and choose the one that matches the content.", "passage": "저는 일곱 시에 일어납니다. 여덟 시까지 아침을 먹습니다. 아홉 시에 학교에 갑니다. 오늘은 비가 와서 우산을 가져갑니다.", "passageGl": "I get up at seven o'clock. I eat breakfast by eight o'clock. I go to school at nine o'clock. Today it is raining, so I take an umbrella.", "options": [{"t": "저는 여섯 시에 일어납니다.", "gl": "I get up at six o'clock."}, {"t": "아침을 안 먹습니다.", "gl": "I do not eat breakfast."}, {"t": "저는 아홉 시에 학교에 갑니다.", "gl": "I go to school at nine o'clock."}, {"t": "우산을 안 가져갑니다.", "gl": "I do not take an umbrella."}], "correct": 2, "explain": "The passage states '아홉 시에 학교에 갑니다', so I go to school at nine o'clock. The other options contradict the passage.", "traps": ["'여섯 시에 일어납니다' is wrong because the passage says '일곱 시'.", "'아침을 안 먹습니다' is wrong because the passage says '아침을 먹습니다'.", "'우산을 안 가져갑니다' is wrong because the passage says '우산을 가져갑니다'."], "tip": "Pay attention to numbers and time expressions such as 일곱 시, 여덟 시, 아홉 시. They often decide the correct answer.", "optExplain": ["오답: 글에서 ‘일곱 시에 일어납니다’라고 했어요.", "오답: 글에서 ‘아침을 먹습니다’라고 했어요.", "정답: 글에서 ‘아홉 시에 학교에 갑니다’라고 했어요.", "오답: 글에서 ‘우산을 가져갑니다’라고 했어요."], "optExplainEn": ["Wrong: The passage says 'I get up at seven o'clock'.", "Wrong: The passage says 'I eat breakfast'.", "Correct: The passage says 'I go to school at nine o'clock'.", "Wrong: The passage says 'I take an umbrella'."], "tipEn": "Pay attention to numbers and time expressions such as 일곱 시, 여덟 시, 아홉 시. They often decide the correct answer.", "freq": 2, "freqNote": "TOPIK I 읽기 19~21 · 세부 내용 이해", "id": "AII-ffef4f"}, {"section": "reading", "type": "order", "level": 1, "points": 2, "q": "다음을 순서에 맞게 배열한 것을 고르십시오.", "qGl": "Choose the one arranged in the correct order.", "passage": "㉠ 저는 아침에 일어나요.\n㉡ 그리고 세수를 해요.\n㉢ 그다음에 밥을 먹어요.\n㉣ 학교에 가요.", "passageGl": "㉠ I wake up in the morning.\n㉡ And I wash my face.\n㉢ Then I eat breakfast.\n㉣ I go to school.", "options": [{"t": "㉠ - ㉡ - ㉢ - ㉣", "gl": "1-2-3-4"}, {"t": "㉠ - ㉢ - ㉡ - ㉣", "gl": "1-3-2-4"}, {"t": "㉡ - ㉠ - ㉢ - ㉣", "gl": "2-1-3-4"}, {"t": "㉠ - ㉡ - ㉣ - ㉢", "gl": "1-2-4-3"}], "correct": 0, "explain": "The correct order follows a typical morning routine: wake up, wash, eat, then go to school. The connecting words '그리고' and '그다음에' signal sequential actions.", "traps": ["Eating before washing is not a natural morning order.", "Washing before waking up is logically impossible in this routine.", "Going to school before eating is less natural than eating breakfast first."], "tip": "순서 문제는 '그리고', '그다음에' 같은 연결 표현과 자연스러운 시간 흐름을 확인하세요.", "optExplain": ["정답: 아침에 일어난 후 세수를 하고, 밥을 먹고, 학교에 가는 순서가 자연스럽습니다.", "오답: 밥을 먹은 후에 세수를 하는 것은 자연스러운 순서가 아닙니다.", "오답: 세수를 먼저 하고 일어나는 것은 논리적으로 맞지 않습니다.", "오답: 학교에 간 후에 밥을 먹는 것은 문맥상 자연스럽지 않습니다."], "optExplainEn": ["Correct: The sequence of waking up, washing, eating, and then going to school is natural.", "Wrong: Eating before washing is not a natural order.", "Wrong: Washing before waking up is logically impossible in this routine.", "Wrong: Going to school before eating is less natural in this morning context."], "tipEn": "For ordering questions, check connecting expressions like '그리고' or '그다음에' and the natural flow of time.", "freq": 2, "freqNote": "TOPIK I 읽기 21~22 · 문장 순서 배열", "id": "AII-59af2b"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "민수는 주말에 무엇을 했습니까?", "qGl": "What did Minsu do on the weekend?", "passage": "민수는 주말에 친구와 영화를 봤어요. 영화가 아주 재미있었어요. 그리고 저녁을 같이 먹었어요.", "passageGl": "Minsu watched a movie with a friend on the weekend. The movie was very fun. And they ate dinner together.", "options": [{"t": "영화를 봤어요.", "gl": "Watched a movie."}, {"t": "책을 읽었어요.", "gl": "Read a book."}, {"t": "운동을 했어요.", "gl": "Exercised."}, {"t": "여행을 갔어요.", "gl": "Went on a trip."}], "correct": 0, "explain": "The passage explicitly states that Minsu watched a movie with a friend on the weekend. The other activities are not mentioned.", "traps": ["Reading a book is a plausible weekend activity but is not mentioned in the passage.", "Exercising is not mentioned; the passage only includes watching a movie and eating dinner.", "Traveling is not mentioned; the passage describes a local outing with a friend."], "tip": "내용 이해 문제는 본문에 나온 정보만으로 답을 고르세요. 지문에 없는 내용은 오답입니다.", "optExplain": ["정답: 본문에서 민수가 주말에 친구와 영화를 봤다고 했습니다.", "오답: 본문에 책을 읽었다는 내용이 없습니다.", "오답: 본문에 운동을 했다는 내용이 없습니다.", "오답: 본문에 여행을 갔다는 내용이 없습니다."], "optExplainEn": ["Correct: The passage says Minsu watched a movie with a friend on the weekend.", "Wrong: There is no mention of reading a book.", "Wrong: There is no mention of exercising.", "Wrong: There is no mention of traveling."], "tipEn": "For comprehension questions, choose only based on the information in the passage; details not mentioned are wrong.", "freq": 2, "freqNote": "TOPIK I 읽기 11~14 · 내용 이해", "id": "AII-c6d7b8"}, {"section": "reading", "type": "grammar", "level": 1, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "저는 아직 한국말을 잘 못해요. 하지만 조금 ( ).", "passageGl": "I still cannot speak Korean well. But a little ( ).", "options": [{"t": "할 수 있어요", "gl": "can do"}, {"t": "할 거예요", "gl": "will do"}, {"t": "했어요", "gl": "did"}, {"t": "하고 있어요", "gl": "am doing"}], "correct": 0, "explain": "The sentence contrasts 'cannot speak well' with 'but can a little.' The grammar -(으)ㄹ 수 있다 expresses ability, so '할 수 있어요' is correct.", "traps": ["'할 거예요' expresses future intention, but the blank is about current ability after '하지만'.", "'했어요' expresses past action, which does not fit the contrast with the present ability.", "'하고 있어요' expresses an ongoing action, but the context requires ability, not progressive action."], "tip": "능력 표현 '-(으)ㄹ 수 있다/없다'는 '잘하다/못하다'와 함께 자주 나옵니다.", "optExplain": ["정답: '할 수 있어요'는 능력을 나타내어 '조금 할 수 있어요'가 자연스럽습니다.", "오답: '할 거예요'는 미래의 계획을 나타내므로 문맥과 맞지 않습니다.", "오답: '했어요'는 과거의 일을 나타내므로 문맥과 맞지 않습니다.", "오답: '하고 있어요'는 현재 진행 중인 일을 나타내므로 어색합니다."], "optExplainEn": ["Correct: '할 수 있어요' expresses ability, so '조금 할 수 있어요' is natural.", "Wrong: '할 거예요' expresses future intention, which does not fit the context.", "Wrong: '했어요' expresses a past action, which does not fit the contrast with the present.", "Wrong: '하고 있어요' expresses an ongoing action, which is awkward because the sentence needs ability."], "tipEn": "Ability expressions '-(으)ㄹ 수 있다/없다' often appear with '잘하다/못하다'.", "freq": 2, "freqNote": "TOPIK I 읽기 1~6 · 문법", "id": "AII-ef0238"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "친구는 무엇을 합니까?", "qGl": "What does the friend do?", "passage": "저는 학생입니다. 오늘은 월요일입니다. 학교에 갑니다. 저는 한국어를 공부합니다. 친구도 한국어를 공부합니다. 우리는 도서관에서 책을 읽습니다.", "passageGl": "I am a student. Today is Monday. I go to school. I study Korean. My friend also studies Korean. We read books at the library.", "options": [{"t": "한국어를 공부합니다", "gl": "studies Korean"}, {"t": "책을 읽습니다", "gl": "reads books"}, {"t": "학교에 갑니다", "gl": "goes to school"}, {"t": "집에서 쉽니다", "gl": "rests at home"}], "correct": 0, "explain": "The passage explicitly states '친구도 한국어를 공부합니다' (My friend also studies Korean), so the friend studies Korean.", "traps": ["The passage says '우리는 도서관에서 책을 읽습니다' (we read books), but the question asks only about the friend, so 'reads books' is not specifically the friend's action.", "'goes to school' is the narrator's action, not the friend's.", "'rests at home' is not mentioned in the passage."], "tip": "지문에서 주어와 행동을 정확히 연결하세요. '친구도'의 '도'는 '또한'이라는 뜻입니다.", "optExplain": ["정답: '친구도 한국어를 공부합니다'라고 했으므로 친구는 한국어를 공부합니다.", "오답: 책을 읽는 것은 '우리'의 행동이지만 친구만의 행동이라고 단정할 수 없습니다.", "오답: 학교에 가는 것은 '저'의 행동입니다.", "오답: 집에서 쉰다는 내용은 글에 없습니다."], "optExplainEn": ["Correct: The passage says 'My friend also studies Korean,' so the friend studies Korean.", "Wrong: Reading books is 'our' action, but it cannot be asserted as the friend's action alone.", "Wrong: Going to school is the narrator's action.", "Wrong: Resting at home is not mentioned in the passage."], "tipEn": "Connect the subject and action precisely in the passage. The particle '도' in '친구도' means 'also'.", "freq": 2, "freqNote": "TOPIK I 읽기 4~8 · 짧은 글 이해", "id": "AII-4bdb49"}, {"section": "reading", "type": "comprehension", "level": 1, "points": 2, "q": "무엇을 준비해야 합니까?", "qGl": "What should you prepare?", "passage": "내일은 비가 옵니다. 날씨가 춥습니다. 우산을 준비하세요. 옷을 따뜻하게 입으세요.", "passageGl": "Tomorrow it will rain. The weather is cold. Prepare an umbrella. Wear warm clothes.", "options": [{"t": "우산과 따뜻한 옷", "gl": "umbrella and warm clothes"}, {"t": "음식과 물", "gl": "food and water"}, {"t": "책과 연필", "gl": "books and pencils"}, {"t": "모자와 선글라스", "gl": "hat and sunglasses"}], "correct": 0, "explain": "The passage advises '우산을 준비하세요' (prepare an umbrella) and '옷을 따뜻하게 입으세요' (wear warm clothes), so the correct preparation is umbrella and warm clothes.", "traps": ["Food and water are not related to the rainy and cold weather.", "Books and pencils are not mentioned in the passage.", "Hats and sunglasses are for sunny weather, not rain."], "tip": "지문의 마지막 두 문장에서 준비할 물건을 찾으세요. '비'와 '춥다'라는 단어가 핵심 힌트입니다.", "optExplain": ["정답: 지문에 '우산을 준비하세요', '옷을 따뜻하게 입으세요'라고 했으므로 우산과 따뜻한 옷을 준비해야 합니다.", "오답: 음식과 물은 비가 오는 날씨와 관련이 없습니다.", "오답: 책과 연필은 학교 준비물일 수 있지만 지문에는 없습니다.", "오답: 모자와 선글라스는 더운 날씨에 필요한 것입니다."], "optExplainEn": ["Correct: The passage says 'Prepare an umbrella' and 'Wear warm clothes,' so you need an umbrella and warm clothes.", "Wrong: Food and water are not related to rainy weather.", "Wrong: Books and pencils may be school supplies, but they are not in the passage.", "Wrong: Hats and sunglasses are needed for hot weather."], "tipEn": "Find the items to prepare in the last two sentences of the passage. The words 'rain' and 'cold' are key hints.", "freq": 2, "freqNote": "TOPIK I 읽기 1~3 · 공지/안내문", "id": "AII-b0f888"}, {"section": "reading", "type": "grammar", "level": 1, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "저는 주말에 친구___ 만나요.", "passageGl": "I meet my friend ___ on the weekend.", "options": [{"t": "을", "gl": "object particle after consonant"}, {"t": "를", "gl": "object particle after vowel"}, {"t": "이", "gl": "subject particle after consonant"}, {"t": "가", "gl": "subject particle after vowel"}], "correct": 1, "explain": "The verb '만나다' (to meet) requires an object, and the noun '친구' ends in a vowel, so the correct object particle is '를'.", "traps": ["'을' is used after nouns with a final consonant, but '친구' has no final consonant.", "'이' is a subject particle, but 'friend' is the object of the verb 'meet'.", "'가' is also a subject particle, not appropriate for the object position."], "tip": "동사 '만나다'는 목적어를 필요로 하므로 목적격 조사를 씁니다. 명사의 받침 유무를 먼저 확인하세요.", "optExplain": ["오답: '을'은 받침 있는 명사 뒤에 쓰는 목적격 조사입니다. '친구'는 받침이 없습니다.", "정답: '만나요'의 목적어가 필요하고, '친구'는 모음으로 끝나므로 '를'을 씁니다.", "오답: '이'는 주격 조사이며, 문장에서 주어가 아닌 목적어 자리입니다.", "오답: '가'도 주격 조사이며, 받침 없는 명사 뒤에 쓰지만 주어가 아닙니다."], "optExplainEn": ["Wrong: '을' is an object particle used after nouns with a final consonant. '친구' has no final consonant.", "Correct: The verb '만나요' needs an object, and '친구' ends in a vowel, so '를' is used.", "Wrong: '이' is a subject particle, but the blank is the object position, not the subject.", "Wrong: '가' is also a subject particle, used after nouns without a final consonant, but it is not for the object."], "tipEn": "The verb '만나다' requires an object, so use the object particle. First check whether the noun has a final consonant.", "freq": 2, "freqNote": "TOPIK I 읽기 11~13 · 조사/어미", "id": "AII-fab1d0"}, {"section": "reading", "type": "grammar", "level": 1, "points": 2, "q": "빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the blank.", "passage": "시간이 ______ 전화해 주세요.", "passageGl": "If you have no time, please call me.", "options": [{"t": "없으면", "gl": "if (you) don't have"}, {"t": "없지만", "gl": "don't have but"}, {"t": "없어서", "gl": "don't have so"}, {"t": "없고", "gl": "don't have and"}], "correct": 0, "explain": "The correct answer is 없으면, which combines 없다 with the conditional ending -(으)면 to mean 'if you don't have time.' This condition naturally connects to the request '전화해 주세요' (please call).", "traps": ["없지만 means 'but (I) don't have,' which introduces contrast, not a condition.", "없어서 means 'because (I) don't have,' giving a reason, so it does not fit a request clause.", "없고 means 'don't have and,' which merely lists facts and does not express the intended condition."], "tip": "Remember that -(으)면 attaches to verb and adjective stems to mean 'if' or 'when.' For the verb 없다, use 없으면.", "optExplain": ["정답: '없으면'은 '시간이 없다'는 조건을 나타내어 '전화해 주세요'와 자연스럽게 연결됩니다.", "오답: '없지만'은 반대 사실을 연결하므로 '전화해 주세요'와 어울리지 않습니다.", "오답: '없어서'는 이유를 나타내므로 요청 문장과 함께 쓰기 어색합니다.", "오답: '없고'는 단순 나열이라 조건의 의미가 없습니다."], "optExplainEn": ["Correct: '없으면' expresses the condition 'if there is no time,' so it connects naturally with 'please call.'", "Wrong: '없지만' links contrasting facts, so it does not match 'please call.'", "Wrong: '없어서' expresses a reason, so it is awkward with a request sentence.", "Wrong: '없고' simply lists facts, so it lacks the meaning of a condition."], "tipEn": "Remember that -(으)면 attaches to verb and adjective stems to mean 'if' or 'when.' For the verb 없다, use 없으면.", "freq": 2, "freqNote": "TOPIK I 읽기 16~18 · 문법 (빈칸 채우기)", "id": "AII-5ecfea"}, {"section": "listening", "type": "comprehension", "level": 1, "points": 2, "q": "가: 수진 씨, 주말에 뭐 했어요?\n나: 친구하고 백화점에 갔어요. 옷을 샀어요.\n가: 그래요? 무슨 옷을 샀어요?\n나: 파란색 치마를 샀어요. 그리고 구두도 샀어요.", "qGl": "A: Sujin, what did you do on the weekend?\nB: I went to the department store with a friend. I bought clothes.\nA: Really? What clothes did you buy?\nB: I bought a blue skirt. And I also bought dress shoes.", "passage": "", "passageGl": "", "options": [{"t": "가방", "gl": "bag"}, {"t": "파란색 치마하고 구두", "gl": "a blue skirt and dress shoes"}, {"t": "모자하고 양말", "gl": "a hat and socks"}, {"t": "바지하고 티셔츠", "gl": "pants and a T-shirt"}], "correct": 1, "explain": "Sujin says she bought a blue skirt and also bought dress shoes at the department store.", "traps": ["A bag is not mentioned anywhere in the dialogue.", "A hat and socks are not mentioned as items she bought.", "Pants and a T-shirt are not mentioned anywhere."], "tip": "Listen for the exact items mentioned after the question '무슨 옷을 샀어요?' — the answer comes right after.", "optExplain": ["오답: 가방은 이야기에 나오지 않았습니다.", "정답: 수진 씨가 파란색 치마하고 구두를 샀다고 말했습니다.", "오답: 모자와 양말은 백화점에서 샀다고 하지 않았습니다.", "오답: 바지와 티셔츠는 언급되지 않았습니다."], "optExplainEn": ["Wrong: A bag is not mentioned in the dialogue.", "Correct: Sujin says she bought a blue skirt and dress shoes.", "Wrong: A hat and socks are not mentioned as purchases.", "Wrong: Pants and a T-shirt are not mentioned."], "tipEn": "Listen for the exact items mentioned after the question '무슨 옷을 샀어요?' — the answer comes right after.", "freq": 2, "freqNote": "TOPIK I 듣기 7~12 · 내용 이해", "audioHint": "가: 주말에 뭐 했어요?\n나: 백화점에서 옷을 샀어요.\n가: 무슨 옷을 샀어요?\n나: 파란색 치마하고 구두를 샀어요.", "id": "AII-3855ec"}, {"section": "listening", "type": "topic", "level": 1, "points": 2, "q": "가: 오늘 날씨가 정말 덥네요.\n나: 네, 너무 더워요. 아이스크림을 먹고 싶어요.\n가: 저도요. 시원한 물도 마시고 싶어요.\n나: 우리 카페에 가서 아이스크림을 먹을까요?", "qGl": "A: The weather is really hot today.\nB: Yes, it's so hot. I want to eat ice cream.\nA: Me too. I also want to drink cold water.\nB: Shall we go to a cafe and eat ice cream?", "passage": "", "passageGl": "", "options": [{"t": "더운 날씨", "gl": "hot weather"}, {"t": "주말 계획", "gl": "weekend plans"}, {"t": "친구 생일", "gl": "friend's birthday"}, {"t": "한국어 공부", "gl": "Korean study"}], "correct": 0, "explain": "The two speakers are talking about the hot weather and wanting to eat or drink something cold.", "traps": ["Weekend plans are not mentioned in the dialogue.", "A friend's birthday is not mentioned.", "Korean study is not mentioned."], "tip": "For topic questions, listen for repeated words like '날씨', '덥다', '아이스크림' to identify the main idea.", "optExplain": ["정답: 두 사람은 날씨가 덥다고 말하고 시원한 것을 먹고 싶다고 이야기합니다.", "오답: 주말에 무엇을 할지는 나오지 않았습니다.", "오답: 친구 생일은 대화에 없습니다.", "오답: 한국어 공부는 언급되지 않았습니다."], "optExplainEn": ["Correct: They talk about the hot weather and wanting something cool.", "Wrong: Weekend plans are not discussed.", "Wrong: A friend's birthday is not mentioned.", "Wrong: Korean study is not mentioned."], "tipEn": "For topic questions, listen for repeated words like '날씨', '덥다', '아이스크림' to identify the main idea.", "freq": 2, "freqNote": "TOPIK I 듣기 11~14 · 주제 고르기", "audioHint": "가: 오늘 날씨가 정말 덥네요.\n나: 네, 아이스크림을 먹고 싶어요.\n가: 카페에 갈까요?", "id": "AII-a81f71"}, {"section": "listening", "type": "intent", "level": 1, "points": 2, "q": "가: 엄마, 저 배고파요.\n나: 그래? 냉장고에 빵이 있어. 조금 먹을까?\n가: 아니요, 저는 밥이 먹고 싶어요.\n나: 알았어. 잠깐 기다려. 지금 밥을 할게.", "qGl": "A: Mom, I'm hungry.\nB: Really? There is bread in the refrigerator. Do you want some?\nA: No, I want to eat rice.\nB: Okay. Wait a moment. I'll make rice now.", "passage": "", "passageGl": "", "options": [{"t": "빵을 사러 갑니다", "gl": "goes to buy bread"}, {"t": "밥을 합니다", "gl": "cooks rice"}, {"t": "텔레비전을 봅니다", "gl": "watches TV"}, {"t": "밖에서 먹습니다", "gl": "eats out"}], "correct": 1, "explain": "The woman says '지금 밥을 할게' meaning she will cook rice now.", "traps": ["The woman does not say she will go buy bread.", "Watching TV is not mentioned.", "Eating out is not suggested."], "tip": "For intention questions, listen for future tense verbs like '할게' or '먹을까' that signal what the speaker will do.", "optExplain": ["오답: 여자는 빵을 사러 간다고 하지 않았습니다.", "정답: 여자는 '지금 밥을 할게'라고 말하며 밥을 지으려고 합니다.", "오답: 텔레비전을 보는 것은 대화에 없습니다.", "오답: 밖에서 먹자는 말은 나오지 않았습니다."], "optExplainEn": ["Wrong: The woman does not say she will go buy bread.", "Correct: The woman says 'I will make rice now', meaning she will cook rice.", "Wrong: Watching TV is not mentioned.", "Wrong: Eating out is not suggested."], "tipEn": "For intention questions, listen for future tense verbs like '할게' or '먹을까' that signal what the speaker will do.", "freq": 2, "freqNote": "TOPIK I 듣기 15~17 · 화자의 의도", "audioHint": "가: 엄마, 배고파요.\n나: 빵 먹을까?\n가: 밥이 먹고 싶어요.\n나: 지금 밥을 할게.", "id": "AII-4fb1c1"}, {"section": "listening", "type": "comprehension", "level": 1, "points": 2, "q": "가: 민수 씨, 내일 뭐 해요?\n나: 친구하고 영화관에 가요. 같이 볼까요?\n가: 좋아요. 몇 시에 만나요?\n나: 두 시에 영화관 앞에서 만나요.", "qGl": "A: Minsu, what are you doing tomorrow? B: I am going to the movie theater with a friend. Shall we watch together? A: Great. What time shall we meet? B: Let's meet in front of the movie theater at two o'clock.", "passage": "", "passageGl": "", "options": [{"t": "영화를 봅니다.", "gl": "(They) watch a movie."}, {"t": "밥을 먹습니다.", "gl": "(They) eat a meal."}, {"t": "쇼핑을 합니다.", "gl": "(They) go shopping."}, {"t": "운동을 합니다.", "gl": "(They) exercise."}], "correct": 0, "explain": "The dialogue says they are going to the movie theater together, so watching a movie is what they will do.", "traps": ["Eating is not mentioned in the dialogue.", "Shopping is not mentioned; the location is a movie theater.", "Exercise is not mentioned; they plan to watch a movie."], "tip": "Listen for place nouns such as 영화관 and action verbs like 보다 — they often signal the main activity.", "optExplain": ["정답: 두 사람이 영화관에 가서 함께 영화를 본다고 했으므로 ‘영화를 봅니다’가 맞습니다.", "오답: 대화에서 밥을 먹는다는 내용은 나오지 않았습니다.", "오답: ‘쇼핑을 합니다’는 영화관이 아니라 상점이나 시장에서 하는 일이라 맞지 않습니다.", "오답: 운동을 한다는 말은 대화에 없습니다."], "optExplainEn": ["Correct: The speakers say they are going to the movie theater to watch a movie together.", "Wrong: The dialogue does not mention eating a meal.", "Wrong: Shopping is done in stores or markets, not a movie theater.", "Wrong: There is no mention of exercising."], "tipEn": "Listen for place nouns such as 영화관 and action verbs like 보다 — they often signal the main activity.", "freq": 2, "freqNote": "TOPIK I 듣기 7~10 · 내용 이해", "audioHint": "가: 내일 뭐 해요? 나: 친구하고 영화관에 가요.", "id": "AII-258291"}, {"section": "listening", "type": "grammar", "level": 1, "points": 2, "q": "가: 주말에 뭐 할 거예요?\n나: ________", "qGl": "A: What will you do on the weekend? B: ________", "passage": "", "passageGl": "", "options": [{"t": "친구하고 영화를 볼 거예요.", "gl": "I will watch a movie with a friend."}, {"t": "친구하고 영화를 봤어요.", "gl": "I watched a movie with a friend."}, {"t": "친구하고 영화를 보고 싶어요.", "gl": "I want to watch a movie with a friend."}, {"t": "친구하고 영화를 보지 마세요.", "gl": "Don't watch a movie with a friend."}], "correct": 0, "explain": "The question asks about a future plan using -(으)ㄹ 거예요, so the answer should also use the future/plan form ‘볼 거예요’.", "traps": ["Past tense ‘봤어요’ cannot answer a future-plan question.", "‘보고 싶어요’ expresses a wish, not a concrete plan in response to ‘할 거예요’.", "‘보지 마세요’ is a negative command and does not answer the question."], "tip": "Match the tense of your answer to the question: 할 거예요 → -(으)ㄹ 거예요.", "optExplain": ["정답: ‘주말에 뭐 할 거예요?’는 미래의 계획을 물으므로 미래·계획 표현 ‘볼 거예요’로 답합니다.", "오답: ‘봤어요’는 과거 표현이라 미래 계획을 묻는 질문에 어울리지 않습니다.", "오답: ‘보고 싶어요’는 희망을 나타내지만 계획을 묻는 질문에는 자연스럽지 않습니다.", "오답: ‘보지 마세요’는 금지 표현으로 질문에 대한 대답이 될 수 없습니다."], "optExplainEn": ["Correct: The question asks about a future plan, so the future/plan form ‘볼 거예요’ is appropriate.", "Wrong: ‘봤어요’ is past tense and does not fit a future-plan question.", "Wrong: ‘보고 싶어요’ expresses a wish, not a concrete plan.", "Wrong: ‘보지 마세요’ is a prohibition, not an answer to the question."], "tipEn": "Match the tense of your answer to the question: 할 거예요 → -(으)ㄹ 거예요.", "freq": 2, "freqNote": "TOPIK I 듣기 11~14 · 대답 고르기", "audioHint": "가: 주말에 뭐 할 거예요?", "id": "AII-58d0f8"}, {"section": "listening", "type": "grammar", "level": 1, "points": 2, "q": "가: 지금 뭐 해요?\n나: ________", "qGl": "A: What are you doing now? B: ________", "passage": "", "passageGl": "", "options": [{"t": "책을 읽고 있어요.", "gl": "I am reading a book."}, {"t": "책을 읽을 수 있어요.", "gl": "I can read a book."}, {"t": "책을 읽을 거예요.", "gl": "I will read a book."}, {"t": "책을 읽지 마세요.", "gl": "Don't read a book."}], "correct": 0, "explain": "‘지금’ with the question ‘뭐 해요?’ asks about an action in progress, so the present progressive ‘-고 있다’ with ‘읽고 있어요’ is correct.", "traps": ["‘읽을 수 있어요’ expresses ability, not what one is doing now.", "‘읽을 거예요’ refers to a future plan, not the current action.", "‘읽지 마세요’ is a negative command and cannot describe what one is doing."], "tip": "If you hear ‘지금 … 뭐 해요?’, listen for an answer with ‘-고 있어요’.", "optExplain": ["정답: ‘지금 뭐 해요?’는 현재 하고 있는 동작을 물으므로 진행형 ‘-고 있어요’를 써서 ‘읽고 있어요’가 맞습니다.", "오답: ‘읽을 수 있어요’는 능력을 나타내므로 지금 하는 일에 대한 대답이 아닙니다.", "오답: ‘읽을 거예요’는 미래의 일을 나타내므로 현재 동작을 묻는 질문에 맞지 않습니다.", "오답: ‘읽지 마세요’는 금지 명령문으로 자기 행동을 설명하는 대답이 될 수 없습니다."], "optExplainEn": ["Correct: The question asks what is happening now, so the progressive form ‘-고 있어요’ is right.", "Wrong: ‘읽을 수 있어요’ expresses ability, not a current action.", "Wrong: ‘읽을 거예요’ is future and does not answer what one is doing now.", "Wrong: ‘읽지 마세요’ is a negative command, not a description of current action."], "tipEn": "If you hear ‘지금 … 뭐 해요?’, listen for an answer with ‘-고 있어요’.", "freq": 2, "freqNote": "TOPIK I 듣기 11~14 · 대답 고르기", "audioHint": "가: 지금 뭐 해요?", "id": "AII-39f49f"}, {"section": "listening", "type": "place", "level": 1, "points": 2, "q": "가: 여기 계산해 주세요. 그리고 포장해 주세요.\n나: 네, 모두 12,000원입니다. 봉투에 넣어 드릴까요?\n가: 네, 감사합니다.", "qGl": "A: Please check me out here, and please wrap this up. B: Okay, the total is 12,000 won. Shall I put it in a bag? A: Yes, thank you.", "passage": "", "passageGl": "", "options": [{"t": "식당", "gl": "restaurant"}, {"t": "도서관", "gl": "library"}, {"t": "우체국", "gl": "post office"}, {"t": "약국", "gl": "pharmacy"}], "correct": 0, "explain": "The speakers mention paying (계산) and packing food (포장), which typically happens at a restaurant.", "traps": ["A library would not ask for packaging food.", "A post office would not handle food packaging.", "A pharmacy would not ask about putting items in a food bag."], "tip": "Listen for keywords like 계산 and 포장 to identify a restaurant or cafe setting.", "optExplain": ["정답: 음식을 계산하고 포장해 달라고 하므로 식당입니다.", "오답: 도서관에서는 음식을 포장해 달라고 하지 않습니다.", "오답: 우체국에서는 음식을 계산하거나 포장하지 않습니다.", "오답: 약국에서는 음식을 봉투에 넣어 드릴까요라고 묻지 않습니다."], "optExplainEn": ["Correct: They ask to pay for and pack food, so it is a restaurant.", "Wrong: In a library, you would not ask to pack food.", "Wrong: In a post office, you would not pay for or pack food.", "Wrong: In a pharmacy, you would not be asked if they should put food in a bag."], "tipEn": "Listen for keywords like 계산 and 포장 to identify a restaurant or cafe setting.", "audioHint": "가: 여기 계산해 주세요. 그리고 포장해 주세요. 나: 네, 봉투에 넣어 드릴까요?", "freq": 2, "freqNote": "TOPIK I 듣기 4~6 · 장소 고르기", "id": "AII-57bbbd"}, {"section": "listening", "type": "intent", "level": 1, "points": 2, "q": "가: 주말에 같이 영화 볼까요?\n나: 미안해요. 주말에는 집에서 쉬고 싶어요.", "qGl": "A: Shall we watch a movie together on the weekend? B: Sorry. I want to rest at home on the weekend.", "passage": "", "passageGl": "", "options": [{"t": "영화를 보고 싶다", "gl": "wants to watch a movie"}, {"t": "집에서 쉬고 싶다", "gl": "wants to rest at home"}, {"t": "같이 밥을 먹고 싶다", "gl": "wants to eat together"}, {"t": "주말에 일하고 싶다", "gl": "wants to work on the weekend"}], "correct": 1, "explain": "The woman says '집에서 쉬고 싶어요', which directly expresses her intention to rest at home.", "traps": ["She rejects the movie invitation, so she does not want to watch a movie.", "She does not mention eating together.", "She says she wants to rest, not work."], "tip": "Focus on the second speaker's verb ending -고 싶다 to understand intention.", "optExplain": ["오답: 영화 보자는 제안을 거절했으므로 영화를 보고 싶은 것이 아닙니다.", "정답: 여자가 '집에서 쉬고 싶어요'라고 말했으므로 집에서 쉬고 싶은 것입니다.", "오답: 같이 밥을 먹자는 말은 대화에 없습니다.", "오답: 쉬고 싶다고 했으므로 일하고 싶은 것이 아닙니다."], "optExplainEn": ["Wrong: She rejects the movie suggestion, so she does not want to watch a movie.", "Correct: The woman says 'I want to rest at home', so she wants to rest at home.", "Wrong: There is no mention of eating together in the dialogue.", "Wrong: She says she wants to rest, so she does not want to work."], "tipEn": "Focus on the second speaker's verb ending -고 싶다 to understand intention.", "audioHint": "가: 주말에 같이 영화 볼까요? 나: 미안해요. 집에서 쉬고 싶어요.", "freq": 2, "freqNote": "TOPIK I 듣기 7~9 · 의도 고르기", "id": "AII-599dd8"}, {"section": "listening", "type": "place", "level": 1, "points": 2, "q": "가: 여기에서 서울역까지 얼마나 걸려요?\n나: 지하철로 30분쯤 걸려요.\n가: 그럼 몇 번 출구로 나가야 해요?\n나: 2번 출구로 나가세요.", "qGl": "A: How long does it take from here to Seoul Station? B: It takes about 30 minutes by subway. A: Then which exit should I take? B: Take exit 2.", "passage": "", "passageGl": "", "options": [{"t": "지하철역", "gl": "subway station"}, {"t": "학교", "gl": "school"}, {"t": "공항", "gl": "airport"}, {"t": "병원", "gl": "hospital"}], "correct": 0, "explain": "They talk about taking the subway, travel time to Seoul Station, and which exit to use, which happens at a subway station.", "traps": ["A school would not ask about subway exits to Seoul Station.", "An airport would not have a 30-minute subway route to Seoul Station as the focus.", "A hospital would not discuss subway exits in this way."], "tip": "Listen for transportation words like 지하철, 출구, and station names.", "optExplain": ["정답: 지하철로 서울역까지 가는 시간과 출구를 묻고 있으므로 지하철역입니다.", "오답: 학교에서는 서울역까지 지하철 시간과 출구를 묻지 않습니다.", "오답: 공항에서는 서울역까지 30분쯤 걸리는 지하철 노선을 주제로 하지 않습니다.", "오답: 병원에서는 서울역 출구를 묻는 대화가 자연스럽지 않습니다."], "optExplainEn": ["Correct: They ask about subway time to Seoul Station and which exit, so it is a subway station.", "Wrong: At a school, you would not ask about subway exit to Seoul Station like this.", "Wrong: At an airport, a 30-minute subway route to Seoul Station would not be discussed this way.", "Wrong: At a hospital, asking about Seoul Station exits is unnatural."], "tipEn": "Listen for transportation words like 지하철, 출구, and station names.", "audioHint": "가: 여기에서 서울역까지 얼마나 걸려요? 나: 지하철로 30분쯤 걸려요.", "freq": 2, "freqNote": "TOPIK I 듣기 10~12 · 장소 고르기", "id": "AII-b87bea"}, {"section": "listening", "type": "comprehension", "level": 1, "points": 2, "q": "가: 주말에 뭐 할 거예요?\n나: 친구하고 영화를 보고 싶어요. 같이 볼까요?\n가: 좋아요. 무슨 영화를 볼 거예요?\n나: 재미있는 한국 영화를 볼 거예요.\n\n들은 내용과 같은 것은 무엇입니까?", "qGl": "A: What are you going to do this weekend?\nB: I want to watch a movie with a friend. Shall we watch together?\nA: Good. What movie are you going to watch?\nB: We are going to watch a fun Korean movie.\n\nWhich one matches what you heard?", "passage": "", "passageGl": "", "options": [{"t": "주말에 친구하고 영화를 봅니다.", "gl": "They watch a movie with a friend on the weekend."}, {"t": "주말에 친구하고 책을 읽습니다.", "gl": "They read a book with a friend on the weekend."}, {"t": "주말에 혼자 한국 영화를 봅니다.", "gl": "They watch a Korean movie alone on the weekend."}, {"t": "주말에 친구하고 운동을 합니다.", "gl": "They exercise with a friend on the weekend."}], "correct": 0, "explain": "The dialogue clearly states the speaker wants to watch a movie with a friend, and the other person agrees, so the matching statement is the first option.", "traps": ["Option 2 confuses 책 with 영화.", "Option 3 misses the phrase 친구하고 and wrongly says alone.", "Option 4 confuses 운동 with 영화."], "tip": "‘-고 싶어요’와 ‘-을 거예요’가 나오면 원하는 일이나 계획을 잘 들으세요. ‘같이’나 ‘친구하고’ 같은 말을 놓치지 마세요.", "optExplain": ["정답: 대화에서 ‘친구하고 영화를 보고 싶어요’라고 했고 ‘같이 볼까요?’에 ‘좋아요’라고 대답했으므로 주말에 친구하고 영화를 봅니다.", "오답: 대화에서 책이나 읽기에 대한 말은 전혀 나오지 않았습니다.", "오답: ‘친구하고’라고 했으므로 혼자가 아니라 친구와 함께 봅니다.", "오답: 운동에 대한 말은 나오지 않았습니다."], "optExplainEn": ["Correct: The dialogue says ‘I want to watch a movie with a friend,’ and the other person agreed by saying ‘Good,’ so they will watch a movie with a friend on the weekend.", "Wrong: There is no mention of books or reading in the dialogue.", "Wrong: The speaker said ‘with a friend,’ so it is not alone.", "Wrong: There is no mention of exercise."], "tipEn": "When you hear ‘-고 싶어요’ and ‘-을 거예요,’ listen carefully for the wish or plan. Don't miss words like ‘같이’ or ‘친구하고.’", "freq": 2, "freqNote": "TOPIK I 듣기 16~21 · 짧은 대화 이해", "audioHint": "가: 주말에 뭐 할 거예요? 나: 친구하고 영화를 보고 싶어요. 같이 볼까요?", "id": "AII-0ba079"}, {"section": "reading", "type": "main_idea", "level": 3, "points": 2, "q": "이 글의 주제로 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate main topic of the passage.", "passage": "요즘 카페에서 일회용 컵 대신 개인 컵을 사용하는 사람들이 늘고 있다. 작은 습관 하나가 쓰레기를 줄이고 환경을 지키는 데 도움이 되기 때문이다. 물론 처음에는 불편할 수 있지만, 조금만 신경 쓰면 누구나 실천할 수 있다.", "passageGl": "Recently, the number of people using their own cups instead of disposable cups at cafes is increasing. This is because one small habit helps reduce waste and protect the environment. Of course, it may be inconvenient at first, but anyone can practice it with a little attention.", "options": [{"t": "환경 보호를 위한 작은 실천", "gl": "Small actions to protect the environment"}, {"t": "일회용 컵의 장점", "gl": "Advantages of disposable cups"}, {"t": "카페에서 커피를 마시는 방법", "gl": "How to drink coffee at a cafe"}, {"t": "재활용 산업의 문제점", "gl": "Problems of the recycling industry"}], "correct": 0, "explain": "The passage explains that the small habit of using a personal cup helps protect the environment, so the main topic is small actions to protect the environment.", "traps": ["Disposable cups are mentioned, but their advantages are not the focus.", "The cafe setting is only a background, not the main idea.", "Recycling is related to the environment, but the passage is about personal cup use, not recycling industry problems."], "tip": "For main idea questions, focus on the repeated or concluding idea rather than single details.", "optExplain": ["정답: 글은 개인 컵 사용이라는 작은 습관이 환경을 지키는 데 도움이 된다고 설명하므로 주제는 환경 보호를 위한 작은 실천입니다.", "오답: 일회용 컵의 장점은 본문에서 언급되지 않았습니다.", "오답: 카페에서 커피를 마시는 방법은 글의 중심 내용이 아닙니다.", "오답: 재활용 산업의 문제점은 본문에 나타나지 않습니다."], "optExplainEn": ["Correct: The passage explains that the small habit of using a personal cup helps protect the environment, so the topic is small actions to protect the environment.", "Wrong: The advantages of disposable cups are not mentioned in the passage.", "Wrong: How to drink coffee at a cafe is not the central content of the passage.", "Wrong: Problems of the recycling industry do not appear in the passage."], "tipEn": "For main idea questions, focus on the repeated or concluding idea rather than single details.", "freq": 2, "freqNote": "TOPIK II 읽기 12~15 · 주제 파악", "id": "AIII-4a3f33"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음 글에서 빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate one to fill in the blank in the following text.", "passage": "민수 씨는 한국에 ( ㉠ ) 3개월이 되었지만 아직 길을 잘 찾지 못한다.", "passageGl": "Minsu has been in Korea for three months, but he still cannot find his way well.", "options": [{"t": "온 지", "gl": "since (he) came"}, {"t": "온 다음에", "gl": "after coming"}, {"t": "올 뻔해서", "gl": "because (he) almost came"}, {"t": "오는 동안", "gl": "while coming"}], "correct": 0, "explain": "'-(으)ㄴ 지' is used to indicate how much time has passed after an action occurred, so '한국에 온 지 3개월이 되었다' is the natural choice.", "traps": ["'온 다음에' expresses a sequence of actions, not elapsed time.", "'올 뻔해서' expresses something that almost happened, which does not fit the context.", "'오는 동안' indicates a period while an action is in progress and cannot be used with '3개월'."], "tip": "For grammar questions, check whether the connecting expression indicates time passed, sequence, or an almost-happened event.", "optExplain": ["정답: '-(으)ㄴ 지'는 어떤 일이 일어난 후 시간이 얼마나 지났는지를 나타내므로 '한국에 온 지 3개월이 되었다'가 자연스럽습니다.", "오답: '온 다음에'는 다음 행동을 연결하는 표현이라 시간이 경과했다는 의미와 어울리지 않습니다.", "오답: '올 뻔해서'는 거의 일어날 뻔한 일을 나타내므로 문맥에 맞지 않습니다.", "오답: '오는 동안'은 행동이 진행되는 시간을 나타내므로 '3개월'과 함께 쓸 수 없습니다."], "optExplainEn": ["Correct: '-(으)ㄴ 지' indicates how much time has passed since an action occurred, so '3 months since coming to Korea' is natural.", "Wrong: '온 다음에' connects a following action and does not fit the meaning of elapsed time.", "Wrong: '올 뻔해서' expresses something that almost happened and does not fit the context.", "Wrong: '오는 동안' indicates a period while an action is in progress and cannot be used with '3 months'."], "tipEn": "For grammar questions, check whether the connecting expression indicates time passed, sequence, or an almost-happened event.", "freq": 2, "freqNote": "TOPIK II 읽기 1~4 · 문법 고르기", "id": "AIII-be629e"}, {"section": "reading", "type": "main_idea", "level": 3, "points": 2, "q": "이 글의 주제로 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate main topic of this passage.", "passage": "많은 사람들이 건강을 위해 특별한 운동을 찾지만, 사실 가장 쉬운 방법은 걷기이다. 걷기는 특별한 도구가 필요 없고 언제 어디서나 할 수 있다. 또 규칙적으로 걸으면 심장이 튼튼해지고 스트레스도 줄어든다. 그래서 바쁜 현대인에게 걷기는 가장 현실적인 건강 관리법이다.", "passageGl": "Many people look for special exercise for health, but in fact the easiest method is walking. Walking does not require special equipment and can be done anytime, anywhere. Also, walking regularly strengthens the heart and reduces stress. Therefore, for busy modern people, walking is the most realistic health care method.", "options": [{"t": "걷기 운동의 효과와 장점", "gl": "Benefits and advantages of walking exercise"}, {"t": "특별한 운동 도구의 필요성", "gl": "The need for special exercise equipment"}, {"t": "현대인의 바쁜 생활", "gl": "The busy life of modern people"}, {"t": "심장 질환의 원인", "gl": "Causes of heart disease"}], "correct": 0, "explain": "The passage consistently explains that walking is an easy, equipment-free, health-strengthening and stress-reducing activity, making it the most realistic health care method. Therefore, the topic is the benefits and advantages of walking exercise.", "traps": ["The absence of equipment is a supporting detail, not the main point.", "Busy modern people are mentioned as the target audience, not the central topic.", "Heart health is one benefit among several, not the whole topic."], "tip": "Distinguish between a supporting detail and the overall theme: ask what the entire passage consistently explains.", "optExplain": ["정답: 글은 걷기가 도구 없이 할 수 있고 심장을 튼튼하게 하며 스트레스를 줄여 주는 현실적인 건강 관리법이라고 설명하므로 주제는 걷기 운동의 효과와 장점입니다.", "오답: 본문은 특별한 도구가 필요 없다고 말할 뿐 도구의 필요성을 강조하지 않습니다.", "오답: 바쁜 현대인은 배경으로 등장할 뿐 글의 중심 주제가 아닙니다.", "오답: 심장 질환의 원인은 언급되지 않았습니다."], "optExplainEn": ["Correct: The passage states that walking can be done without equipment, strengthens the heart, and reduces stress as a realistic health care method, so the topic is the benefits and advantages of walking exercise.", "Wrong: The passage says no special equipment is needed, so it does not emphasize the need for equipment.", "Wrong: Busy modern people appear only as background and are not the central topic.", "Wrong: Causes of heart disease are not mentioned."], "tipEn": "Distinguish between a supporting detail and the overall theme: ask what the entire passage consistently explains.", "freq": 2, "freqNote": "TOPIK II 읽기 12~15 · 주제 파악", "id": "AIII-fb3c3b"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음 밑줄 친 부분에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the underlined part.", "passage": "한국에 온 __________ 3년이 지났다.", "passageGl": "It has been 3 years since I came to Korea.", "options": [{"t": "-(으)ㄴ 지", "gl": "since (time elapsed)"}, {"t": "-다가", "gl": "while doing / then"}, {"t": "-았/었으면 좋겠다", "gl": "wish / hope"}, {"t": "-(으)ㄹ 수밖에 없다", "gl": "have no choice but to"}], "correct": 0, "explain": "The blank requires a connector that expresses elapsed time after a past action. '-(으)ㄴ 지' combined with a time expression like '3년이 지났다' means 'it has been 3 years since...'", "traps": ["'-다가' is tempting for action-related sentences but signals interruption, not time passed.", "'-았/었으면 좋겠다' is for wishes, not time.", "'-(으)ㄹ 수밖에 없다' indicates inevitability, not duration."], "tip": "Remember the pattern: [verb] + (으)ㄴ 지 + time + 되다/지나다 means 'it has been [time] since [verb]'.", "optExplain": ["정답: '한국에 온 지 3년이 지났다'는 어떤 행동이 끝난 후 시간이 지났음을 나타내는 표현으로 '-(으)ㄴ 지'가 알맞습니다.", "오답: '-다가'는 동작이 전환되거나 중단됨을 나타내므로 시간 경과 의미가 없습니다.", "오답: '-았/었으면 좋겠다'는 바람이나 희망을 나타내므로 문장의 시간 경과 의미와 맞지 않습니다.", "오답: '-(으)ㄹ 수밖에 없다'는 어쩔 수 없이 해야만 함을 나타내므로 여기서는 어울리지 않습니다."], "optExplainEn": ["Correct: '한국에 온 지 3년이 지났다' expresses how much time has passed since an action ended, so '-(으)ㄴ 지' is appropriate.", "Wrong: '-다가' indicates an action switched or was interrupted, not elapsed time.", "Wrong: '-았/었으면 좋겠다' expresses a wish, not the time elapsed meaning in the sentence.", "Wrong: '-(으)ㄹ 수밖에 없다' means having no choice but to do something, so it does not fit here."], "tipEn": "Remember the pattern: [verb] + (으)ㄴ 지 + time + 되다/지나다 means 'it has been [time] since [verb]'.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 문법", "id": "AIII-c9a412"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 3, "q": "다음 글의 내용과 같은 것을 고르십시오.", "qGl": "Choose the statement that matches the content of the passage.", "passage": "요즘 많은 직장인들이 점심을 거르고 일을 한다. 그러나 점심을 거르면 오후에 집중력이 떨어지고 쉽게 피곤해진다. 전문가들은 바쁘더라도 간단한 음식이라도 규칙적으로 먹는 것이 건강에 좋다고 말한다.", "passageGl": "These days, many office workers skip lunch and work. However, if you skip lunch, your concentration drops in the afternoon and you get tired easily. Experts say that even if you are busy, it is good for your health to eat regularly, even a simple meal.", "options": [{"t": "직장인들은 점심을 먹으면 집중력이 떨어진다.", "gl": "Office workers lose concentration when they eat lunch."}, {"t": "점심을 거르면 오후에 집중력이 떨어진다.", "gl": "If you skip lunch, your concentration drops in the afternoon."}, {"t": "전문가들은 음식을 많이 먹으라고 권했다.", "gl": "Experts advised people to eat a lot of food."}, {"t": "바쁜 사람은 식사를 거르는 것이 좋다.", "gl": "Busy people should skip meals."}], "correct": 1, "explain": "The passage states clearly that skipping lunch leads to lower afternoon concentration and tiredness. Option 1 (index 1) is the only one that reflects that exact cause-effect relationship.", "traps": ["Option 0 reverses cause and effect.", "Option 2 exaggerates 'eating regularly' into 'eating a lot'.", "Option 3 contradicts the expert advice to eat even a simple meal."], "tip": "For content-matching questions, read the passage carefully and compare each option word-by-word against the text. Avoid options that change degree or add information.", "optExplain": ["오답: 글은 점심을 거르면 집중력이 떨어진다고 했을 뿐, 먹으면 떨어진다고 하지 않았습니다.", "정답: '점심을 거르면 오후에 집중력이 떨어지고 쉽게 피곤해진다'는 문장과 일치합니다.", "오답: 전문가들은 많이 먹으라고 권하지 않고 규칙적으로 먹는 것이 좋다고 했습니다.", "오답: 바쁘더라도 식사를 거르지 말고 간단한 음식이라도 먹으라고 했습니다."], "optExplainEn": ["Wrong: The text says concentration drops when you skip lunch, not when you eat it.", "Correct: This matches the sentence 'If you skip lunch, your concentration drops in the afternoon and you get tired easily.'", "Wrong: Experts did not recommend eating a lot, but eating regularly.", "Wrong: The text says even if busy, do not skip meals, but eat something simple."], "tipEn": "For content-matching questions, read the passage carefully and compare each option word-by-word against the text. Avoid options that change degree or add information.", "freq": 2, "freqNote": "TOPIK II 읽기 11~12 · 내용 일치", "id": "AIII-9d655a"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음 밑줄 친 부분에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate word to fill in the underlined part.", "passage": "일이 너무 많아서 오늘 밤에 늦게까지 __________.", "passageGl": "There is so much work that I have no choice but to work late tonight.", "options": [{"t": "할 수밖에 없다", "gl": "have no choice but to do"}, {"t": "한 지", "gl": "since did"}, {"t": "하다가", "gl": "while doing / then"}, {"t": "했으면 좋겠다", "gl": "wish had done"}], "correct": 0, "explain": "The sentence expresses an unavoidable situation due to too much work. '-(으)ㄹ 수밖에 없다' means 'there is no choice but to...' and is the only option that conveys inevitability.", "traps": ["'한 지' is a time expression, not a consequence.", "'하다가' is about interruption, not obligation.", "'했으면 좋겠다' expresses hope, not inevitability."], "tip": "To choose connectors, first identify the logical relationship: reason→inevitable result uses '-(으)ㄹ 수밖에 없다'.", "optExplain": ["정답: '할 수밖에 없다'는 다른 방법이 없어 어쩔 수 없이 그렇게 해야 함을 나타내므로 문맥에 알맞습니다.", "오답: '한 지'는 어떤 일이 끝난 후 시간이 지났음을 나타내므로 '일이 많아서' 이유와 어울리지 않습니다.", "오답: '하다가'는 동작이 전환되거나 중단됨을 나타내므로 늦게까지 일해야 하는 필연의 의미가 없습니다.", "오답: '했으면 좋겠다'는 바람이나 희망을 나타내므로 '일이 너무 많다'는 이유의 결과로는 어색합니다."], "optExplainEn": ["Correct: '할 수밖에 없다' means there is no other way and one is forced to do it, fitting the context.", "Wrong: '한 지' indicates time elapsed after an action ended, so it does not fit the reason 'because there is so much work'.", "Wrong: '하다가' indicates an action was interrupted or switched, lacking the necessity meaning of working late.", "Wrong: '했으면 좋겠다' expresses a wish, not the inevitable result of having too much work."], "tipEn": "To choose connectors, first identify the logical relationship: reason→inevitable result uses '-(으)ㄹ 수밖에 없다'.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 문법", "id": "AIII-6f1a25"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음을 읽고 ( )에 들어갈 가장 알맞은 것을 고르십시오.\n한국에 ( ) 벌써 두 달이 됐어요.", "qGl": "Read the following and choose the most appropriate word to enter in the blank.\nIt has already been two months since I came to Korea.", "passage": "", "passageGl": "", "options": [{"t": "온 지", "gl": "since I came"}, {"t": "온 후에", "gl": "after I came"}, {"t": "오기 전에", "gl": "before I came"}, {"t": "오는 동안", "gl": "while I was coming"}], "correct": 0, "explain": "‘-(으)ㄴ 지’ expresses the amount of time that has passed since a past action happened. The sentence ‘한국에 온 지 벌써 두 달이 됐어요’ correctly means ‘It has already been two months since I came to Korea.’", "traps": ["‘온 후에’ means ‘after coming,’ which does not combine naturally with the elapsed-time expression ‘벌써 두 달이 됐다.’", "‘오기 전에’ means ‘before coming,’ which creates the opposite meaning of the sentence.", "‘오는 동안’ means ‘while coming,’ which refers to the process of coming rather than time elapsed after arriving."], "tip": "Remember the pattern ‘-(으)ㄴ 지 + time + 됐다’ to talk about how long it has been since something happened.", "optExplain": ["정답: ‘-(으)ㄴ 지’는 어떤 일이 일어난 후 지난 시간을 나타낼 때 쓰므로 ‘한국에 온 지 벌써 두 달이 됐어요’가 자연스럽습니다.", "오답: ‘온 후에’는 ‘온 다음에’라는 뜻으로 시간의 경과를 나타내는 ‘벌써 두 달이 됐다’와 호응하지 않습니다.", "오답: ‘오기 전에’는 한국에 오기 전이라는 뜻이므로 문장의 의미와 반대가 됩니다.", "오답: ‘오는 동안’은 오는 과정 중이라는 뜻으로 시간 경과 표현과 어울리지 않습니다."], "optExplainEn": ["Correct: ‘-(으)ㄴ 지’ expresses the time that has passed since an action occurred, so ‘한국에 온 지 벌써 두 달이 됐어요’ is natural.", "Wrong: ‘온 후에’ means ‘after coming,’ so it does not combine naturally with the elapsed-time expression ‘벌써 두 달이 됐다.’", "Wrong: ‘오기 전에’ means ‘before coming to Korea,’ so it creates the opposite meaning of the sentence.", "Wrong: ‘오는 동안’ means ‘while coming,’ which refers to the process of coming and does not fit the elapsed-time expression."], "tipEn": "Remember the pattern ‘-(으)ㄴ 지 + time + 됐다’ to talk about how long it has been since something happened.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 문법 빈칸", "id": "AIII-4c0ba2"}, {"section": "reading", "type": "grammar", "level": 3, "points": 2, "q": "다음을 읽고 ( )에 들어갈 가장 알맞은 것을 고르십시오.\n집에 ( ) 비가 오기 시작했다.", "qGl": "Read the following and choose the most appropriate word to enter in the blank.\nIt started raining while I was going home.", "passage": "", "passageGl": "", "options": [{"t": "가다가", "gl": "while going"}, {"t": "가서", "gl": "went and then"}, {"t": "가니까", "gl": "since I went"}, {"t": "가지만", "gl": "but I go"}], "correct": 0, "explain": "‘-다가’ indicates that an action was in progress when another action or event occurred. ‘집에 가다가 비가 오기 시작했다’ means ‘It started raining while I was going home,’ which is the intended meaning.", "traps": ["‘가서’ indicates sequential actions, meaning ‘went home and then,’ which does not fit the meaning of an event occurring during the action.", "‘가니까’ expresses a reason or cause, so it would awkwardly suggest that going home caused the rain to start.", "‘가지만’ expresses contrast, so ‘집에 가지만 비가 오기 시작했다’ sounds unnatural and does not show interruption."], "tip": "Use ‘-다가’ when a second action interrupts or occurs during the first action.", "optExplain": ["정답: ‘-다가’는 어떤 행동이 진행되는 중에 다른 일이 일어남을 나타내므로 ‘집에 가다가 비가 오기 시작했다’가 자연스럽습니다.", "오답: ‘가서’는 순차적인 행동을 나타내어 ‘집에 간 후에’라는 뜻이 되어 문장에 맞지 않습니다.", "오답: ‘가니까’는 원인이나 이유를 나타내므로 ‘비가 오기 시작했다’의 원인으로는 어색합니다.", "오답: ‘가지만’은 대조의 의미로 ‘집에 가지만 비가 오기 시작했다’는 자연스럽지 않습니다."], "optExplainEn": ["Correct: ‘-다가’ indicates that another event occurs while an action is in progress, so ‘집에 가다가 비가 오기 시작했다’ is natural.", "Wrong: ‘가서’ indicates sequential actions, meaning ‘went home and then,’ so it does not fit the sentence.", "Wrong: ‘가니까’ expresses a reason or cause, so it awkwardly suggests going home caused the rain to start.", "Wrong: ‘가지만’ expresses contrast, so ‘집에 가지만 비가 오기 시작했다’ is unnatural and does not show interruption."], "tipEn": "Use ‘-다가’ when a second action interrupts or occurs during the first action.", "freq": 2, "freqNote": "TOPIK II 읽기 1~2 · 문법 빈칸", "id": "AIII-ccebbc"}, {"section": "reading", "type": "comprehension", "level": 3, "points": 2, "q": "이 글의 주제로 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate topic for this passage.", "passage": "요즘 많은 사람들이 건강을 위해 걷기 운동을 시작하고 있다. 걷기는 특별한 장비 없이 언제 어디서나 할 수 있고, 부상 위험이 적다. 전문가들은 매일 30분씩만 걸어도 심장병 예방에 도움이 된다고 말한다.", "passageGl": "These days, many people are starting walking exercise for their health. Walking can be done anytime and anywhere without special equipment, and it has a low risk of injury. Experts say that walking just 30 minutes every day helps prevent heart disease.", "options": [{"t": "걷기 운동의 장점", "gl": "the advantages of walking exercise"}, {"t": "걷기 운동의 역사", "gl": "the history of walking exercise"}, {"t": "심장병 치료 방법", "gl": "methods of treating heart disease"}, {"t": "운동 장비 고르는 법", "gl": "how to choose exercise equipment"}], "correct": 0, "explain": "The passage lists several advantages of walking exercise: it needs no special equipment, can be done anytime and anywhere, has a low risk of injury, and helps prevent heart disease. Therefore, the topic is the benefits of walking exercise.", "traps": ["The history of walking exercise is not mentioned anywhere in the passage.", "The passage says walking helps prevent heart disease, but it does not discuss methods of treating heart disease.", "Choosing exercise equipment is not discussed; on the contrary, the passage says walking can be done without special equipment."], "tip": "For topic questions, look for the repeated idea or the claim that all sentences support. Here, every sentence supports a different advantage of walking.", "optExplain": ["정답: 지문은 특별한 장비가 없고 부상 위험이 적으며 심장병 예방에 도움이 된다는 걷기 운동의 여러 장점을 설명하고 있습니다.", "오답: 걷기 운동이 언제 시작되었는지 역사적 내용은 지문에 전혀 나오지 않습니다.", "오답: 지문은 심장병을 치료하는 방법이 아니라 예방에 도움이 된다고만 언급합니다.", "오답: 지문은 운동 장비를 고르는 법이 아니라 장비 없이도 가능하다는 점을 말합니다."], "optExplainEn": ["Correct: The passage explains several advantages of walking exercise, such as needing no special equipment, having a low risk of injury, and helping prevent heart disease.", "Wrong: The history of walking exercise is not mentioned anywhere in the passage.", "Wrong: The passage mentions preventing heart disease, not treating heart disease.", "Wrong: The passage does not discuss choosing exercise equipment; it says walking can be done without special equipment."], "tipEn": "For topic questions, look for the repeated idea or the claim that all sentences support. Here, every sentence supports a different advantage of walking.", "freq": 2, "freqNote": "TOPIK II 읽기 5~8 · 주제 찾기", "id": "AIII-98f280"}, {"section": "reading", "type": "vocab", "level": 3, "points": 2, "q": "다음 ( )에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "Choose the most appropriate thing to fill in the blank.", "passage": "오랜 시간 준비한 만큼 결과가 좋게 나와서 모든 노력이 ( ).", "passageGl": "Since the result turned out well in proportion to the long preparation, all the effort was ( ).", "options": [{"t": "보람 있었다", "gl": "was worthwhile"}, {"t": "낭비였다", "gl": "was a waste"}, {"t": "부족했다", "gl": "was insufficient"}, {"t": "가능했다", "gl": "was possible"}], "correct": 0, "explain": "The blank needs a word meaning that the effort was rewarding. ‘보람 있다’ expresses a sense of worthwhile achievement, matching the positive result after long preparation.", "traps": ["'낭비였다' means the effort was wasted, which contradicts the good result.", "'부족했다' means insufficient, which does not describe effort being worthwhile.", "'가능했다' means possible, which does not fit the idea that effort paid off."], "tip": "Study collocations like '노력이 보람 있다' (effort is worthwhile) and reread the whole sentence with each option.", "optExplain": ["정답: ‘보람 있다’는 들인 노력에 대해 만족스럽고 값진 느낌이 있다는 뜻으로, 오랜 준비 끝에 결과가 좋게 나온 문맥과 자연스럽게 어울립니다.", "오답: ‘낭비였다’는 노력이 헛되었다는 뜻이므로, 결과가 좋게 나왔다는 내용과 반대가 됩니다.", "오답: ‘부족했다’는 필요한 정도에 미치지 못했다는 뜻으로, 모든 노력이 값지게 느껴지는 상황과 어울리지 않습니다.", "오답: ‘가능했다’는 어떤 일을 할 수 있게 되었다는 뜻일 뿐, 노력의 가치를 표현하지는 않습니다."], "optExplainEn": ["Correct: ‘보람 있다’ means to feel satisfied and that one's effort was worthwhile, which fits the context of a good result after long preparation.", "Wrong: ‘낭비였다’ means the effort was wasted, which contradicts the statement that the result turned out well.", "Wrong: ‘부족했다’ means it was insufficient or lacking, so it does not describe effort that feels rewarding.", "Wrong: ‘가능했다’ means something became possible, but it does not express that the effort was valuable."], "tipEn": "Study collocations like '노력이 보람 있다' (effort is worthwhile) and reread the whole sentence with each option.", "freq": 2, "freqNote": "TOPIK II 읽기 1~4 · 어휘", "id": "AIII-666786"}, {"section": "listening", "type": "grammar", "level": 3, "points": 2, "q": "다음을 듣고 여자가 이어서 할 말로 가장 알맞은 것을 고르십시오.\n가: 어제 제안한 보고서 수정 건은 어떻게 됐어요?\n나: 김 과장님이 퇴근 전까지 고쳐 놓으라고 하셔서 방금 끝냈어요.\n가: 고생 많았어요. 이제 퇴근해도 되죠?\n나: 네, 그런데 내일 아침 회의 자료를 아직 다 준비하지 못해서요.\n가: 내일 아침까지는 시간이 있으니까 괜찮지 않아요?", "qGl": "Listen and choose the most appropriate next line for the woman.\nA: What happened with the report revision I suggested yesterday?\nB: Manager Kim told me to finish it before leaving work, so I just finished it.\nA: That must have been tough. You can leave now, right?\nB: Yes, but I haven't finished preparing the materials for tomorrow morning's meeting yet.\nA: You still have time until tomorrow morning, so it's okay, right?", "audioHint": "가: 보고서 수정 건은 어떻게 됐어요?\n나: 방금 끝냈어요. 그런데 내일 아침 회의 자료를 아직 다 준비하지 못해서요.\n가: 내일 아침까지는 시간이 있으니까 괜찮지 않아요?", "passage": "", "passageGl": "", "options": [{"t": "회의 자료를 미리 준비해 놓아서 이제 퇴근해도 걱정이 없어요.", "gl": "I prepared the meeting materials in advance, so I don't need to worry about leaving now."}, {"t": "회의 자료를 준비하는 중이라서 조금 더 남아서 일해야 해요.", "gl": "I am still preparing the meeting materials, so I need to stay and work a little longer."}, {"t": "회의 자료를 준비했을 뻔해서 다행이에요.", "gl": "I almost prepared the meeting materials, so I am relieved."}, {"t": "회의 자료를 준비한 지 한 시간이 지났어요.", "gl": "It has been an hour since I prepared the meeting materials."}], "correct": 1, "explain": "The woman says that she has not finished preparing tomorrow morning's meeting materials. The most natural next line is that she is still preparing them, so she needs to stay and work a little longer.", "traps": ["Option 0 assumes the preparation is already complete, but the woman says it isn't.", "Option 2 uses -(으)ㄹ 뻔했다, which means something almost happened but did not, so it does not match the ongoing preparation.", "Option 3 adds unrelated time information and ignores the woman's remaining task."], "tip": "When choosing the next line in a dialogue, use the grammar and situation from the last speaker's line. -(으)ㄴ/는 중이다 indicates that an action is currently in progress.", "optExplain": ["오답: 여자는 자료를 아직 다 준비하지 못했다고 했으므로 준비해 놓았다는 말은 대화 내용과 맞지 않습니다.", "정답: 여자는 내일 회의 자료를 아직 준비하는 중이라고 했으므로 조금 더 남아서 일하겠다는 응답이 가장 자연스럽습니다.", "오답: ‘준비했을 뻔했다’는 실제로는 준비하지 않았다는 뜻이므로 자료를 준비 중인 상황과 다릅니다.", "오답: 자료를 준비한 지 한 시간이 지났다는 정보는 대화에 나오지 않으며 여자의 남은 일과도 맞지 않습니다."], "optExplainEn": ["Wrong: The woman said she has not finished preparing the materials, so saying she prepared them in advance contradicts the dialogue.", "Correct: The woman is still preparing the morning meeting materials, so it is most natural for her to say she will stay a little longer.", "Wrong: ‘Almost prepared’ means she did not actually prepare, which does not match her ongoing preparation.", "Wrong: The dialogue does not mention how long it has been since she prepared, and it does not match her remaining task."], "tipEn": "When choosing the next line in a dialogue, use the grammar and situation from the last speaker's line. -(으)ㄴ/는 중이다 indicates that an action is currently in progress.", "freq": 2, "freqNote": "TOPIK II 듣기 4~8 · 이어질 응답 고르기 (문법: -는 중이다)", "id": "AIII-a089c8"}, {"section": "listening", "type": "intent", "level": 3, "points": 2, "q": "다음을 듣고 여자가 이번 주말에 하려고 하는 일로 가장 알맞은 것을 고르십시오.\n가: 주말에 뭐 할 거예요?\n나: 친구들이랑 같이 봉사활동을 가려고요.\n가: 어떤 봉사활동인데요?\n나: 동네 공원에서 쓰레기를 줍고 나무에 물을 주는 일이에요.\n가: 뜻깊네요. 비가 오면 어떻게 해요?\n나: 비가 오면 다음 주로 미뤄질 수도 있어요.", "qGl": "Listen and choose what the woman is planning to do this weekend.\nA: What are you going to do on the weekend?\nB: I'm planning to go do volunteer work with my friends.\nA: What kind of volunteer work?\nB: Picking up trash and watering trees in the neighborhood park.\nA: That's meaningful. What if it rains?\nB: If it rains, it may be postponed to next week.", "audioHint": "가: 주말에 뭐 할 거예요?\n나: 친구들이랑 봉사활동을 가려고요.\n가: 어떤 봉사활동인데요?\n나: 공원에서 쓰레기를 줍고 나무에 물을 주는 일이에요.", "passage": "", "passageGl": "", "options": [{"t": "공원에서 운동을 하려고 한다.", "gl": "She is planning to exercise in the park."}, {"t": "친구들과 여행을 가려고 한다.", "gl": "She is planning to travel with friends."}, {"t": "공원에서 봉사활동을 하려고 한다.", "gl": "She is planning to do volunteer work in the park."}, {"t": "비가 와서 집에서 쉬려고 한다.", "gl": "She is planning to rest at home because it will rain."}], "correct": 2, "explain": "The woman says she is planning to go volunteer work with her friends. The volunteer work involves picking up trash and watering trees in the neighborhood park.", "traps": ["Option 0 changes volunteer work into exercise, which is not what she said.", "Option 1 says travel, but she said volunteer work, not a trip.", "Option 3 assumes she will rest at home, but she only said the activity may be postponed if it rains."], "tip": "For intent questions, listen for the verb ending -(으)려고 하다. It signals the speaker's plan or intention.", "optExplain": ["오답: 여자는 공원에서 쓰레기를 줍는다고 했지 운동을 한다고 하지 않았습니다.", "오답: 친구들과 함께 가기는 하지만 여행이 아니라 봉사활동을 가려고 한다고 했습니다.", "정답: 여자는 친구들과 동네 공원에서 쓰레기를 줍고 나무에 물을 주는 봉사활동을 하려고 한다고 했습니다.", "오답: 비가 오면 다음 주로 미뤄질 수도 있다고 했을 뿐 집에서 쉬겠다고 하지 않았습니다."], "optExplainEn": ["Wrong: The woman said she would pick up trash in the park, not exercise.", "Wrong: She is going with friends, but she said she is going to do volunteer work, not travel.", "Correct: The woman said she is planning to do volunteer work with friends, picking up trash and watering trees in the neighborhood park.", "Wrong: She only said it may be postponed to next week if it rains; she did not say she would rest at home."], "tipEn": "For intent questions, listen for the verb ending -(으)려고 하다. It signals the speaker's plan or intention.", "freq": 2, "freqNote": "TOPIK II 듣기 4~8 · 화자의 의도/계획 파악", "id": "AIII-9ee637"}, {"section": "listening", "type": "topic", "level": 3, "points": 2, "q": "다음을 듣고 두 사람이 대화하고 있는 주제로 가장 알맞은 것을 고르십시오.\n가: 요즘 아침에 일어나기가 너무 힘들어요.\n나: 저도 그래요. 밤에 잠이 잘 안 와서 휴대폰을 계속 보게 돼요.\n가: 저는 자기 전에 따뜻한 물로 샤워를 하면 좀 도움이 되는 것 같아요.\n나: 그래요? 저는 커피를 오후에 마시면 잠을 못 자서 안 마시려고요.", "qGl": "Listen and choose the topic the two people are talking about.\nA: These days it's so hard to wake up in the morning.\nB: Me too. I can't sleep well at night, so I keep looking at my phone.\nA: I feel like taking a warm shower before bed helps a little.\nB: Really? I can't sleep if I drink coffee in the afternoon, so I'm trying not to drink it.", "audioHint": "가: 요즘 아침에 일어나기가 너무 힘들어요.\n나: 저도 밤에 잠이 안 와서 휴대폰을 봐요.\n가: 저는 자기 전에 따뜻한 샤워를 하면 도움이 되는 것 같아요.", "passage": "", "passageGl": "", "options": [{"t": "수면 습관과 건강", "gl": "Sleep habits and health"}, {"t": "휴대폰 사용법", "gl": "How to use a phone"}, {"t": "샤워 시설 고장", "gl": "A broken shower facility"}, {"t": "커피 맛 비교", "gl": "Comparing coffee flavors"}], "correct": 0, "explain": "The two people are talking about how hard it is to wake up in the morning, why they cannot sleep well, and what they do to sleep better. This is about sleep habits and health.", "traps": ["Option 1 is too narrow: the phone is mentioned as a habit when they cannot sleep, not as a topic.", "Option 2 invents a broken shower; the shower is mentioned as something that helps with sleep.", "Option 3 is wrong because they do not compare coffee flavors; they only mention coffee as a cause of poor sleep."], "tip": "For topic questions, look for repeated words and the overall situation: waking up hard, sleeping poorly, and ways to sleep better all point to sleep habits and health.", "optExplain": ["정답: 두 사람은 아침에 일어나기 힘든 것과 잠을 잘 자기 위해 하는 노력 등 수면 습관에 대해 이야기하고 있습니다.", "오답: 휴대폰 사용법이 아니라 잠이 안 올 때 휴대폰을 본다는 경험을 언급했을 뿐입니다.", "오답: 샤워 시설이 고장 났다는 내용은 나오지 않았고 자기 전 샤워가 도움이 된다고 했습니다.", "오답: 커피의 맛을 비교하지 않았고 커피를 마시면 잠을 못 잔다는 영향만 말했습니다."], "optExplainEn": ["Correct: The two people are talking about sleep habits, including difficulty waking up and efforts to sleep better.", "Wrong: They are not discussing how to use a phone; they only mention looking at the phone when they cannot sleep.", "Wrong: There is no mention of a broken shower; they say taking a shower before bed helps.", "Wrong: They do not compare coffee flavors; they only say coffee prevents them from sleeping well."], "tipEn": "For topic questions, look for repeated words and the overall situation: waking up hard, sleeping poorly, and ways to sleep better all point to sleep habits and health.", "freq": 2, "freqNote": "TOPIK II 듣기 9~12 · 대화 주제 고르기", "id": "AIII-ce6d88"}, {"section": "listening", "type": "comprehension", "level": 3, "points": 2, "q": "가: 요즘 얼굴이 안 좋아 보여요. 무슨 일 있어요?\n나: 네, 요즘 야근 때문에 잠을 거의 못 잤어요. 계속 머리도 아프고요.\n가: 그럼 병원에 가 보지 그래요? 회사 앞에 새로 생긴 병원이 아주 친절하다고 하던데요.\n나: 그래요? 약만 먹고 버티고 있었는데, 지금 바로 다녀와야겠네요.\n가: 네, 빨리 다녀오세요.\n\n질문: 여자가 이어서 할 행동으로 알맞은 것을 고르십시오.", "qGl": "A: You look unwell these days. Is something wrong?\nB: Yes, I've barely slept because of overtime work lately. I've also had a constant headache.\nA: Then why don't you go to the hospital? I heard a newly opened hospital in front of your office is very kind.\nB: Really? I've just been taking medicine and enduring it, so I should go right now.\nA: Yes, hurry and go.\n\nQuestion: Choose the action the woman will most likely do next.", "audioHint": "여자는 야근 때문에 잠을 못 자고 머리도 아파서 병원에 가려고 합니다.", "passage": "", "passageGl": "", "options": [{"t": "회사에 출근한다", "gl": "Goes to work"}, {"t": "병원에 간다", "gl": "Goes to the hospital"}, {"t": "약을 먹는다", "gl": "Takes medicine"}, {"t": "잠을 잔다", "gl": "Sleeps"}], "correct": 1, "explain": "The woman says she has been unable to sleep and has a headache, and after hearing about the hospital she says she will go right now. Therefore the next action is going to the hospital.", "traps": ["Going to work is not what she decides to do next; she is currently suffering from overtime work.", "Taking medicine is what she had been doing, but she decides to go to the hospital instead.", "Sleeping is not stated as her immediate action even though she is sleep-deprived."], "tip": "For listening comprehension, listen for time expressions like '지금 바로' and verbs of movement like '다녀오다' to identify the next action.", "optExplain": ["정답: 여자가 회사 앞 병원이 친절하다는 말을 듣고 지금 바로 다녀오겠다고 했으므로 병원에 간다.", "오답: 여자는 이미 회사 일을 하고 있지만 지금 회사에 출근한다고 말하지 않았다.", "오답: 약을 먹고 버티고 있었다고 했으므로 약을 먹는 것은 지금 하려는 행동이 아니다.", "오답: 잠을 거의 못 잤다고 했지만 당장 잠을 자러 간다는 말은 없었다."], "optExplainEn": ["Correct: The woman hears that the hospital in front of her office is kind and says she will go right away, so she goes to the hospital.", "Wrong: She is already working, but she does not say she will go to work now.", "Wrong: She says she has been enduring with medicine, so taking medicine is not her next action.", "Wrong: She says she has barely slept, but she does not say she will go to sleep right now."], "tipEn": "For listening comprehension, listen for time expressions like 'right now' and movement verbs like 'go and come back' to identify the next action.", "freq": 2, "freqNote": "TOPIK II 듣기 1~3 · 이어서 할 행동 고르기", "id": "AIII-04a2e0"}, {"section": "listening", "type": "intent", "level": 3, "points": 2, "q": "가: 이번 주말에 친구들이랑 등산 가기로 했는데 비가 올 것 같아요.\n나: 아침 일찍 출발하면 어때요? 비 오기 전에 산행을 끝낼 수 있어요.\n가: 새벽부터 일어나는 건 힘들 것 같아요. 다른 방법 없을까요?\n나: 그러면 등산 대신 실내 체육관에서 함께 운동하는 것이 어때요?\n가: 좋아요. 비가 오면 그렇게 해요.\n\n질문: 남자가 '실내 체육관에서 함께 운동하는 것이 어때요?'라고 한 의도를 고르십시오.", "qGl": "A: I planned to go hiking with friends this weekend, but I think it will rain.\nB: How about leaving early in the morning? You can finish the hike before it rains.\nA: Getting up at dawn seems hard. Isn't there another way?\nB: Then how about exercising together at an indoor gym instead of hiking?\nA: Good. If it rains, let's do that.\n\nQuestion: Choose the man's intention when he says, 'How about exercising together at an indoor gym?'", "audioHint": "비가 올까 봐 걱정하는 여자에게 남자가 등산 대신 실내 체육관에서 운동하자고 제안합니다.", "passage": "", "passageGl": "", "options": [{"t": "등산을 포기하지 말자고 격려하려고", "gl": "To encourage her not to give up hiking"}, {"t": "비 오기 전에 산행을 끝내자고 제안하려고", "gl": "To suggest finishing the hike before it rains"}, {"t": "비가 와도 할 수 있는 대안을 제안하려고", "gl": "To suggest an alternative that can be done even if it rains"}, {"t": "실내 체육관에 함께 가자고 약속하려고", "gl": "To promise to go to the indoor gym together"}], "correct": 2, "explain": "The woman says getting up early is hard, so the man proposes exercising at an indoor gym as an alternative that can be done even if it rains.", "traps": ["The man is not mainly encouraging her to continue hiking; he offers a different location.", "Finishing the hike before it rains was his earlier suggestion, but the indoor gym line is a new alternative, not the same intention.", "He suggests the idea and the woman agrees, but '약속하다' is too strong; he has not made a fixed promise."], "tip": "For intent questions, focus on the speaker's final suggestion after the other person expresses difficulty. Words like '대신' and '그러면' signal an alternative proposal.", "optExplain": ["정답: 여자가 새벽에 일어나는 것이 힘들다고 하자 남자는 등산 대신 비가 와도 할 수 있는 실내 체육관에서 운동하는 것을 대안으로 제안했다.", "오답: 남자는 등산을 포기하지 말자고 격려한 것이 아니라 대체 장소를 제안했다.", "오답: 비 오기 전에 산행을 끝내자는 것은 남자가 처음에 한 말이지만 '실내 체육관에서 함께 운동하는 것이 어때요?'의 의도는 아니다.", "오답: 남자는 실내 체육관에 함께 가자고 약속한 것이 아니라 제안을 했고 여자가 동의한 것이다."], "optExplainEn": ["Correct: When the woman says waking up early is hard, the man proposes exercising at an indoor gym as an alternative that can be done even if it rains.", "Wrong: The man does not encourage her to keep hiking; he proposes an alternative place.", "Wrong: Finishing the hike before it rains was his first comment, but it is not the intention of the indoor gym line.", "Wrong: The man does not promise to go together; he only suggests it and the woman agrees."], "tipEn": "For intent questions, focus on the speaker's final suggestion after the other person expresses difficulty. Words like 'instead' and 'then' signal an alternative proposal.", "freq": 2, "freqNote": "TOPIK II 듣기 4~6 · 화자의 의도 고르기", "id": "AIII-84d328"}, {"section": "listening", "type": "grammar", "level": 3, "points": 2, "q": "가: 어제 회의에 왜 안 왔어요?\n나: 갑자기 배가 아파서 병원에 다녀오느라고 회의에 못 갔어요.\n가: 그래요? 많이 아픈 것 같은데 이제 괜찮아요?\n나: 네, 다행히 많이 좋아졌어요. 회의 자료는 미리 ______.\n\n질문: 빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "A: Why didn't you come to the meeting yesterday?\nB: I had a sudden stomachache, so I went to the hospital and couldn't attend the meeting.\nA: Really? You seemed very sick. Are you okay now?\nB: Yes, fortunately I'm much better. I ______ the meeting materials in advance.\n\nQuestion: Choose the most appropriate word to fill in the blank.", "audioHint": "회의에 못 갔지만 회의 자료는 미리 준비해 두었다는 대화입니다.", "passage": "", "passageGl": "", "options": [{"t": "준비해 놓았어요", "gl": "prepared in advance"}, {"t": "준비할 뻔했어요", "gl": "almost prepared"}, {"t": "준비하는 중이에요", "gl": "am preparing"}, {"t": "준비한 지 오래됐어요", "gl": "it has been a long time since I prepared"}], "correct": 0, "explain": "'준비해 놓았어요' means the materials were prepared in advance and remain ready. This fits the context that the speaker could not attend the meeting but had already completed the preparation.", "traps": ["'준비할 뻔했어요' means the speaker almost prepared, which does not match the context of completed preparation.", "'준비하는 중이에요' means the speaker is preparing right now, which conflicts with '미리'.", "'준비한 지 오래됐어요' means a long time has passed since preparing, which does not explain the current meeting situation."], "tip": "Focus on '-아/어 놓다' for actions completed in advance for later use. Distinguish it from '-는 중이다' for ongoing actions and '-(으)ㄹ 뻔했다' for something almost happening.", "optExplain": ["정답: '미리 준비해 놓았어요'는 미리 준비를 끝내 두었다는 의미로, 회의에 못 갔지만 자료는 이미 준비되어 있다는 상황에 가장 자연스럽다.", "오답: '준비할 뻔했어요'는 거의 준비할 뻔했다는 뜻으로 문맥에 맞지 않다.", "오답: '준비하는 중이에요'는 지금 준비하고 있다는 뜻으로 '미리'와 어울리지 않는다.", "오답: '준비한 지 오래됐어요'는 준비한 시점이 오래되었다는 뜻으로 대화 상황과 연결되지 않는다."], "optExplainEn": ["Correct: 'Prepared in advance' means the preparation was completed beforehand and remains ready, which fits the situation where the speaker missed the meeting but the materials were already prepared.", "Wrong: 'Almost prepared' means the speaker nearly prepared, which does not match the context.", "Wrong: 'Am preparing' means the speaker is preparing now, which conflicts with 'in advance'.", "Wrong: 'It has been a long time since I prepared' means the preparation happened long ago and does not connect to the meeting situation."], "tipEn": "Focus on '-아/어 놓다' for actions completed in advance for later use. Distinguish it from '-는 중이다' for ongoing actions and '-(으)ㄹ 뻔했다' for something almost happening.", "freq": 2, "freqNote": "TOPIK II 듣기 10~12 · 문법·표현 고르기", "id": "AIII-443c8b"}, {"section": "listening", "type": "topic", "level": 3, "points": 2, "q": "가: 요즘 아침마다 공원에서 가볍게 뛰는데, 같이할래요?\n나: 좋아요. 그런데 저는 오래 못 뛰어서요. 처음부터 너무 빨리 뛰면 금방 지칠 것 같아요.\n가: 걱정 마세요. 천천히 걸으면서 시작해요. 건강을 위해서 꾸준히 하는 게 중요하니까요.\n나: 네, 그럼 내일 아침에 만나요.\n두 사람이 무엇에 대해 이야기하고 있습니까?", "qGl": "A: These days I lightly jog in the park every morning. Would you like to join me?\nB: Sure, but I can't run for long. If I run too fast from the start, I think I'll get tired quickly.\nA: Don't worry. Let's start by walking slowly. For your health, it's important to do it consistently.\nB: Okay, let's meet tomorrow morning then.\nWhat are the two people talking about?", "passage": "", "passageGl": "", "options": [{"t": "새 직장 구하기", "gl": "Looking for a new job"}, {"t": "같이 운동하기", "gl": "Exercising together"}, {"t": "이사할 집 알아보기", "gl": "Looking for a house to move into"}, {"t": "여행 계획 세우기", "gl": "Making travel plans"}], "correct": 1, "explain": "The speakers talk about running in the park, exercising, starting slowly, and meeting tomorrow to exercise together. Therefore, the conversation is about exercising together.", "traps": ["There is no mention of employment or a workplace.", "The conversation does not involve finding a house or moving.", "They are not planning a trip or deciding on a destination."], "tip": "Listen for repeated topic vocabulary such as '뛰다', '건강', and '꾸준히' to identify the main subject of a dialogue.", "optExplain": ["오답: 직장이나 일자리에 대한 언급이 전혀 없습니다.", "정답: 두 사람은 공원에서 함께 뛰고 꾸준히 운동하자고 이야기하고 있으므로 대화 주제는 ‘같이 운동하기’입니다.", "오답: 집이나 이사에 관한 표현이 나오지 않습니다.", "오답: 여행지나 일정을 정하는 내용이 아닙니다."], "optExplainEn": ["Wrong: There is no mention of a job or workplace.", "Correct: The two people talk about running in the park and exercising consistently, so the topic is ‘exercising together.’", "Wrong: There is no expression about a house or moving.", "Wrong: The conversation is not about deciding a travel destination or schedule."], "tipEn": "Listen for repeated vocabulary such as '뛰다', '건강', and '꾸준히' to identify the main subject of a dialogue.", "freq": 2, "freqNote": "TOPIK II 듣기 4~8 · 주제 고르기", "audioHint": "가: 요즘 아침마다 공원에서 뛰는데 같이할래요? 나: 좋아요. 천천히 시작해요.", "id": "AIII-3ec3b7"}, {"section": "listening", "type": "grammar", "level": 3, "points": 2, "q": "가: 어제 야근하느라 많이 피곤했죠?\n나: 네, 일이 늦게까지 끝나지 않은 ( ) 비까지 와서 집에 가기 정말 힘들었어요.\n가: 그래도 오늘은 일찍 끝났으니까 푹 쉬어요.\n빈칸에 들어갈 가장 알맞은 것을 고르십시오.", "qGl": "A: You must have been very tired from working overtime yesterday.\nB: Yes, the work did not finish until late, and on top of that it rained, so it was really hard to get home.\nA: Still, since it ended early today, get some rest.\nChoose the most appropriate option to fill in the blank.", "passage": "", "passageGl": "", "options": [{"t": "데다가", "gl": "In addition; on top of that"}, {"t": "반면에", "gl": "Whereas; on the other hand"}, {"t": "척하다", "gl": "To pretend"}, {"t": "는 중이다", "gl": "To be in the middle of doing"}], "correct": 0, "explain": "The phrase '-는 데다가' means 'in addition to' and is used to add the fact that it rained on top of the fact that the work did not finish until late.", "traps": ["'-는 반면에' is used for contrasting two different situations, not for adding information.", "'-는 척하다' means to pretend, which does not fit the meaning of adding an unfortunate situation.", "'-는 중이다' expresses that an action is currently in progress, not that another fact is added."], "tip": "Study connectors in pairs: '-는 데다가' adds information, while '-는 반면에' contrasts information.", "optExplain": ["정답: ‘-는 데다가’는 앞의 사실에 뒤의 사실을 더할 때 쓰므로 일이 끝나지 않은 상황에 비까지 더해진 내용에 알맞습니다.", "오답: ‘-는 반면에’는 서로 반대되는 내용을 대조할 때 사용합니다.", "오답: ‘-는 척하다’는 실제 사실을 숨기고 다른 행동을 할 때 사용합니다.", "오답: ‘-는 중이다’는 어떤 행동이 진행되고 있을 때 사용합니다."], "optExplainEn": ["Correct: '-는 데다가' is used to add a later fact to an earlier one, so it fits the situation where rain is added to the work not finishing.", "Wrong: '-는 반면에' is used to contrast opposite content.", "Wrong: '-는 척하다' is used when someone hides the truth and acts differently.", "Wrong: '-는 중이다' is used when an action is in progress."], "tipEn": "Study connectors in pairs: '-는 데다가' adds information, while '-는 반면에' contrasts information.", "freq": 2, "freqNote": "TOPIK II 듣기 9~13 · 문법 고르기", "audioHint": "가: 어제 야근하느라 피곤했죠? 나: 일이 끝나지 않은 ( ) 비까지 와서 힘들었어요.", "id": "AIII-720a75"}, {"section": "listening", "type": "intent", "level": 3, "points": 2, "q": "가: 주말에 가구 박람회에 같이 갈래요?\n나: 좋아요. 그런데 저는 새로 이사한 집에 둘 책상이 필요해서요. 서재에 놓을 만한 걸 찾고 싶어요.\n가: 그럼 토요일 오전에 시청역에서 만나요. 요즘 할인을 많이 한다니까 좋은 기회일 거예요.\n나: 네, 그때 봐요.\n여자가 이번 주말에 하려고 하는 일은 무엇입니까?", "qGl": "A: Do you want to go to the furniture exhibition together this weekend?\nB: Sure. But I need a desk for the house I newly moved into. I want to find something to put in my study.\nA: Then let's meet at City Hall Station on Saturday morning. I heard there are many discounts these days, so it will be a good opportunity.\nB: Okay, see you then.\nWhat does the woman intend to do this weekend?", "passage": "", "passageGl": "", "options": [{"t": "이사할 집 알아보기", "gl": "Looking for a house to move into"}, {"t": "남자에게 책상 선물하기", "gl": "Giving the man a desk as a gift"}, {"t": "마음에 드는 책상 사기", "gl": "Buying a desk she likes"}, {"t": "가구 박람회 일 돕기", "gl": "Helping with work at the furniture exhibition"}], "correct": 2, "explain": "The woman says she needs a desk for the house she moved into and wants to find one to put in her study. Therefore, she intends to buy a desk she likes.", "traps": ["She is not looking for a house to move into; she already moved and needs a desk for that house.", "She is not giving a desk to the man; she is buying one for her own study.", "She is not helping at the exhibition; she is going there as a visitor to buy something."], "tip": "For intention questions, focus on expressions such as '~필요해서요', '~찾고 싶어요', or '~하려고요' that reveal the speaker's plan.", "optExplain": ["오답: 이사할 집을 찾는 것이 아니라 이미 이사한 집에 필요한 책상을 찾는 내용입니다.", "오답: 남자에게 책상을 주려는 것이 아니라 자신의 서재에 둘 책상을 사려는 것입니다.", "정답: 여자는 새로 이사한 집에 둘 책상이 필요하다고 했고, 박람회에 가서 마음에 드는 것을 찾고 싶다고 했으므로 책상을 사려고 하는 것입니다.", "오답: 박람회에서 일을 하려는 것이 아니라 방문해서 물건을 사려는 것입니다."], "optExplainEn": ["Wrong: She is not looking for a house to move into; she already moved and needs a desk for that house.", "Wrong: She is not giving a desk to the man; she is buying one for her own study.", "Correct: The woman says she needs a desk for the house she moved into and wants to find something she likes at the exhibition, so she intends to buy a desk.", "Wrong: She is not helping at the exhibition; she is going there as a visitor to buy something."], "tipEn": "For intention questions, focus on expressions such as '~필요해서요', '~찾고 싶어요', or '~하려고요' that reveal the speaker's plan.", "freq": 2, "freqNote": "TOPIK II 듣기 14~17 · 의도 고르기", "audioHint": "가: 주말에 가구 박람회에 같이 갈래요? 나: 새로 이사한 집에 둘 책상을 찾고 싶어요.", "id": "AIII-eb5d9e"}, {"section": "listening", "type": "topic", "level": 3, "points": 3, "q": "가: 요즘 건강이 안 좋아서 걱정이에요.\n나: 저도 그래서 아침마다 공원에서 걷기 시작했어요.\n가: 효과가 있어요?\n나: 네, 매일 30분씩 걸었더니 밤에 잠도 잘 자고 몸도 가벼워진 것 같아요.\n가: 저도 내일부터 같이 해야겠어요.\n두 사람이 무엇에 대해 이야기하고 있습니까?", "qGl": "A: I'm worried because my health hasn't been good lately.\nB: Me too, so I started walking in the park every morning.\nA: Does it help?\nB: Yes, after walking 30 minutes every day, I sleep well at night and my body feels lighter.\nA: I should join you starting tomorrow.\nWhat are the two people talking about?", "passage": "", "passageGl": "", "options": [{"t": "날씨", "gl": "weather"}, {"t": "운동", "gl": "exercise"}, {"t": "음식", "gl": "food"}, {"t": "쇼핑", "gl": "shopping"}], "correct": 1, "explain": "The conversation centers on walking in the park every morning and how it improves sleep and makes the body feel lighter, so the topic is exercise.", "traps": ["Weather is not mentioned at any point in the conversation.", "Food is not discussed; the speakers only talk about walking and health.", "Shopping does not appear; the focus is on exercise and its effects."], "tip": "For topic questions, listen for the main repeated words (걷기, 운동, 건강) and ask what the speakers are mainly discussing, not just any single word you hear.", "optExplain": ["오답: 대화에서 날씨에 대한 언급은 전혀 없습니다.", "정답: 두 사람은 매일 걷기 운동을 하는 것과 건강에 미치는 효과에 대해 이야기하고 있습니다.", "오답: 음식은 대화에 등장하지 않습니다.", "오답: 쇼핑에 대한 내용은 나오지 않습니다."], "optExplainEn": ["Wrong: The conversation never mentions the weather.", "Correct: The two people talk about walking every day and its health effects, so the topic is exercise.", "Wrong: Food does not appear in the conversation.", "Wrong: Shopping is not mentioned."], "tipEn": "For topic questions, listen for the main repeated words (걷기, 운동, 건강) and ask what the speakers are mainly discussing, not just any single word you hear.", "freq": 2, "freqNote": "TOPIK II 듣기 4~8 · 대화 주제 파악", "audioHint": "가: 요즘 건강이 안 좋아 걱정이에요.\n나: 저는 공원에서 걷기 시작했어요.\n가: 효과가 있어요?\n나: 네, 잠도 잘 자고 몸도 가벼워졌어요.", "id": "AIII-5646a7"}];
